export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * @returns {String} the string with all zeroes contained in a <span>
 */
export function spanAllZeroes(s: string): string {
  return escapeHtml(s).replace(/(0+)/g, '<span class="zero">$1</span>');
}

/**
 * @returns {String} the string with each character contained in a <span>
 */
export function spanAll(s: string, offset: number = 0): string {
  const letters = s.split('');

  return letters
    .map(
      (n, i) =>
        `<span class="digit value-${escapeHtml(n)} position-${i + offset}">${spanAllZeroes(n)}</span>`,
    )
    .join('');
}

function spanLeadingZeroesSimple(group: string): string {
  return escapeHtml(group).replace(/^(0+)/, '<span class="zero">$1</span>');
}

/**
 * @returns {String} the string with leading zeroes contained in a <span>
 */
export function spanLeadingZeroes(address: string): string {
  const groups = address.split(':');

  return groups.map((g) => spanLeadingZeroesSimple(g)).join(':');
}

/**
 * Groups an address
 * @returns {String} a grouped address
 */
export function simpleGroup(addressString: string, offset: number = 0): string[] {
  const groups = addressString.split(':');

  return groups.map((g, i) => {
    if (/group-v4/.test(g)) {
      return g;
    }

    return `<span class="hover-group group-${i + offset}">${spanLeadingZeroesSimple(g)}</span>`;
  });
}

import * as v6 from './constants';

export function groupPossibilities(possibilities: string[]): string {
  return `(${possibilities.join('|')})`;
}

export function padGroup(group: string): string {
  if (group.length < 4) {
    return `0{0,${4 - group.length}}${group}`;
  }

  return group;
}

export const ADDRESS_BOUNDARY = '[^A-Fa-f0-9:]';

export function simpleRegularExpression(groups: string[]) {
  const zeroIndexes: number[] = [];

  groups.forEach((group, i) => {
    const groupInteger = parseInt(group, 16);

    if (groupInteger === 0) {
      zeroIndexes.push(i);
    }
  });

  // You can technically elide a single 0, this creates the regular expressions
  // to match that eventuality
  const possibilities = zeroIndexes.map((zeroIndex) =>
    groups
      .map((group, i) => {
        if (i === zeroIndex) {
          const elision = i === 0 || i === v6.GROUPS - 1 ? ':' : '';

          return groupPossibilities([padGroup(group), elision]);
        }

        return padGroup(group);
      })
      .join(':'),
  );

  // The simplest case
  possibilities.push(groups.map(padGroup).join(':'));

  return groupPossibilities(possibilities);
}

export function possibleElisions(
  elidedGroups: number,
  moreLeft?: boolean,
  moreRight?: boolean,
): string {
  const left = moreLeft ? '' : ':';
  const right = moreRight ? '' : ':';

  const possibilities = [];

  // 1. elision of everything (::)
  if (!moreLeft && !moreRight) {
    possibilities.push('::');
  }

  // 2. complete elision of the middle
  if (moreLeft && moreRight) {
    possibilities.push('');
  }

  if ((moreRight && !moreLeft) || (!moreRight && moreLeft)) {
    // 3. complete elision of one side
    possibilities.push(':');
  }

  // 4. elision from the left side
  possibilities.push(`${left}(:0{1,4}){1,${elidedGroups - 1}}`);

  // 5. elision from the right side
  possibilities.push(`(0{1,4}:){1,${elidedGroups - 1}}${right}`);

  // 6. no elision
  possibilities.push(`(0{1,4}:){${elidedGroups - 1}}0{1,4}`);

  // 7. elision (including sloppy elision) from the middle
  for (let groups = 1; groups < elidedGroups - 1; groups++) {
    for (let position = 1; position < elidedGroups - groups; position++) {
      possibilities.push(
        `(0{1,4}:){${position}}:(0{1,4}:){${elidedGroups - position - groups - 1}}0{1,4}`,
      );
    }
  }

  return groupPossibilities(possibilities);
}

import { pinoHttp } from 'pino-http';

import { logger } from '../utils/logger.js';

export const requestLogger = pinoHttp({ logger });

import { Router } from 'express';
import { z } from 'zod';

import { authLimiter } from '../middleware/rateLimit.js';
import { requireAuth } from '../middleware/requireAuth.js';
import { sessionsWithdrawn } from '../realtime/socket.js';
import { validateBody } from '../middleware/validate.js';
import {
  authenticateUser,
  changePassword,
  findUserById,
  registerUser,
} from '../services/authService.js';
import { clearAuthCookie, setAuthCookie } from '../utils/authCookie.js';
import { isCommonPassword } from '../utils/commonPasswords.js';
import { HttpError } from '../utils/httpError.js';
import { logger } from '../utils/logger.js';
import { maxPasswordBytes } from '../utils/password.js';
import { signToken } from '../utils/token.js';

/** What a password has to be for an account to accept it. */
const newPassword = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .refine(
    (value) => Buffer.byteLength(value) <= maxPasswordBytes,
    `Password must be ${maxPasswordBytes} bytes or fewer`,
  )
  .refine((value) => !isCommonPassword(value), 'That password is too common to use');

// zod 4 moved email off string()
const registerSchema = z.object({
  email: z.email('Enter a valid email address'),
  password: newPassword,
  name: z.string().trim().min(1).max(100).optional(),
});

// no rules on the password here - an old password should still be able to log
// in, whatever it would fail today. capping the length would lock out an
// account made before the cap, since bcrypt only ever compares 72 bytes
const loginSchema = z.object({
  email: z.email('Enter a valid email address'),
  password: z.string().min(1, 'Password is required'),
});

const changePasswordSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  newPassword,
});

export const authRouter = Router();

authRouter.post('/register', authLimiter, validateBody(registerSchema), async (req, res) => {
  const { user, tokenVersion } = await registerUser(req.body);

  setAuthCookie(res, signToken(user.id, tokenVersion));

  res.status(201).json({ user });
});

authRouter.post('/login', authLimiter, validateBody(loginSchema), async (req, res) => {
  const { user, tokenVersion } = await authenticateUser(req.body.email, req.body.password);

  setAuthCookie(res, signToken(user.id, tokenVersion));

  res.json({ user });
});

authRouter.post('/logout', (_req, res) => {
  clearAuthCookie(res);

  logger.info('User logged out');

  res.status(204).send();
});

authRouter.get('/me', requireAuth, async (req, res) => {
  if (req.userId === undefined) {
    throw new HttpError(401, 'Authentication required');
  }

  const user = await findUserById(req.userId);

  if (user === null) {
    throw new HttpError(401, 'Authentication required');
  }

  res.json({ user });
});

authRouter.patch(
  '/password',
  authLimiter,
  requireAuth,
  validateBody(changePasswordSchema),
  async (req, res) => {
    if (req.userId === undefined) {
      throw new HttpError(401, 'Authentication required');
    }

    const version = await changePassword(
      req.userId,
      req.body.currentPassword,
      req.body.newPassword,
    );

    // the handshake only checks the version once, so the sockets the old
    // sessions opened have to be dropped rather than left running
    sessionsWithdrawn(req.userId);

    // every other session is now holding an older version, so this one needs a
    // fresh cookie or the change would sign the person doing it out too
    setAuthCookie(res, signToken(req.userId, version));

    res.status(204).send();
  },
);

import type { NextFunction, Request, Response } from 'express';

import { sessionIsCurrent } from '../services/authService.js';
import { AUTH_COOKIE } from '../utils/authCookie.js';
import { HttpError } from '../utils/httpError.js';
import { readToken } from '../utils/token.js';

/** Blocks the request unless it has a valid, current session cookie. */
export async function requireAuth(req: Request, _res: Response, next: NextFunction): Promise<void> {
  const rejection = new HttpError(401, 'Authentication required');

  const token = req.cookies?.[AUTH_COOKIE] as string | undefined;
  if (token === undefined) {
    next(rejection);
    return;
  }

  const session = readToken(token);
  if (session === null) {
    next(rejection);
    return;
  }

  // the signature only proves the token was issued, not that it still stands.
  // this is the read that makes changing a password end the other sessions
  try {
    if (!(await sessionIsCurrent(session))) {
      next(rejection);
      return;
    }
  } catch (error) {
    next(error);
    return;
  }

  req.userId = session.userId;
  next();
}

/** The id requireAuth put on the request. */
export function currentUserId(req: Request): number {
  if (req.userId === undefined) {
    throw new HttpError(401, 'Authentication required');
  }

  return req.userId;
}

import { prisma } from '../db/prisma.js';
import { HttpError } from '../utils/httpError.js';
import { logger } from '../utils/logger.js';
import { hashPassword, verifyPassword } from '../utils/password.js';
import type { Session } from '../utils/token.js';

/** A user as another account sees them, on a note they own or were shared. */
export interface UserSummary {
  id: number;
  email: string;
  name: string | null;
}

/** A user without the password hash. */
export interface PublicUser extends UserSummary {
  createdAt: Date;
}

/** A user and the token generation their sessions must carry. */
export interface SignedInUser {
  user: PublicUser;
  tokenVersion: number;
}

/** The fields of a user that may be shown to a different account. */
export const userSummaryFields = { id: true, email: true, name: true } as const;

const publicFields = { ...userSummaryFields, createdAt: true } as const;

/** Picks only the fields a client may see. */
function toPublicUser(user: PublicUser): PublicUser {
  return { id: user.id, email: user.email, name: user.name, createdAt: user.createdAt };
}

/** Lowercases and trims an address so one account cannot be made twice. */
export function normaliseEmail(email: string): string {
  return email.trim().toLowerCase();
}

// compared against when no account matched, so both branches take the same time
const decoyHash: Promise<string> = hashPassword('there is no account with this address');
decoyHash.catch(() => undefined);

/** Creates a user. Throws 409 if the email is taken. */
export async function registerUser(input: {
  email: string;
  password: string;
  name?: string;
}): Promise<SignedInUser> {
  const passwordHash = await hashPassword(input.password);

  try {
    const user = await prisma.user.create({
      data: {
        email: normaliseEmail(input.email),
        passwordHash,
        name: input.name ?? null,
      },
      select: { ...publicFields, tokenVersion: true },
    });

    logger.info({ userId: user.id }, 'User registered');

    return { user: toPublicUser(user), tokenVersion: user.tokenVersion };
  } catch (error) {
    // P2002 is prisma's unique constraint code. letting the database refuse the
    // duplicate avoids the race a findUnique-then-create would have
    if ((error as { code?: string }).code === 'P2002') {
      throw new HttpError(409, 'That email is already registered');
    }

    throw error;
  }
}

/** Returns the user if the credentials are right, throws 401 if not. */
export async function authenticateUser(email: string, password: string): Promise<SignedInUser> {
  const user = await prisma.user.findUnique({
    where: { email: normaliseEmail(email) },
    select: { ...publicFields, passwordHash: true, tokenVersion: true },
  });

  const invalid = new HttpError(401, 'Invalid email or password');

  if (user === null) {
    await verifyPassword(password, await decoyHash);
    logger.warn('Failed login');
    throw invalid;
  }

  if (!(await verifyPassword(password, user.passwordHash))) {
    logger.warn({ userId: user.id }, 'Failed login');
    throw invalid;
  }

  logger.info({ userId: user.id }, 'User logged in');

  return { user: toPublicUser(user), tokenVersion: user.tokenVersion };
}

/** True if the token still matches the generation the account is on. */
export async function sessionIsCurrent(session: Session): Promise<boolean> {
  const user = await prisma.user.findUnique({
    where: { id: session.userId },
    select: { tokenVersion: true },
  });

  return user !== null && user.tokenVersion === session.tokenVersion;
}

/**
 * Changes a password and ends every other session.
 *
 * Returns the new token version, so the caller can reissue a cookie and leave
 * the session doing the changing signed in.
 */
export async function changePassword(
  userId: number,
  currentPassword: string,
  newPassword: string,
): Promise<number> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { passwordHash: true },
  });

  if (user === null) {
    throw new HttpError(401, 'Authentication required');
  }

  if (!(await verifyPassword(currentPassword, user.passwordHash))) {
    logger.warn({ userId }, 'Failed password change');
    throw new HttpError(401, 'Current password is incorrect');
  }

  if (await verifyPassword(newPassword, user.passwordHash)) {
    throw new HttpError(400, 'New password must be different from the current one');
  }

  const updated = await prisma.user.update({
    where: { id: userId },
    data: { passwordHash: await hashPassword(newPassword), tokenVersion: { increment: 1 } },
    select: { tokenVersion: true },
  });

  logger.info({ userId }, 'Password changed');

  return updated.tokenVersion;
}

/** Finds a user by id, or null if the account is gone. */
export function findUserById(id: number): Promise<PublicUser | null> {
  return prisma.user.findUnique({ where: { id }, select: publicFields });
}

/** Finds a user by address, normalised the same way registering normalises it. */
export function findUserByEmail(email: string): Promise<UserSummary | null> {
  return prisma.user.findUnique({
    where: { email: normaliseEmail(email) },
    select: userSummaryFields,
  });
}

import { PrismaMariaDb } from '@prisma/adapter-mariadb';

import { env } from '../config/env.js';
import { PrismaClient } from '../generated/prisma/client.js';

// mysql 8.4 authenticates with caching_sha2_password. the first login after the
// server starts is not in its cache yet, so the client has to fetch the server's
// public key, and the driver refuses to do that unless asked. set here rather
// than in DATABASE_URL so the prisma migrate engine still gets a plain url.
const connectionUrl = new URL(env.databaseUrl);

// fetching that key over an unencrypted connection weakens the protection
// against a man in the middle, so it is limited to local development. a real
// deployment should connect over TLS, which removes the need for it entirely.
if (env.nodeEnv !== 'production') {
  connectionUrl.searchParams.set('allowPublicKeyRetrieval', 'true');
}

// prisma 7 talks to the database through a driver adapter rather than a url
// declared in schema.prisma
const adapter = new PrismaMariaDb(connectionUrl.toString());

/** Shared Prisma client. One instance is reused for the whole process. */
export const prisma = new PrismaClient({ adapter });

/**
 * True if the database answers a trivial query within the timeout, false if it
 * is unreachable or too slow.
 */
export async function isDatabaseReachable(timeoutMs = 2000): Promise<boolean> {
  // the driver sits and waits on an unreachable host for far longer than a
  // health check should, so the probe gets its own deadline. without this the
  // route hangs and the test suite times out whenever the database is stopped.
  let timer: NodeJS.Timeout | undefined;

  const deadline = new Promise<never>((_resolve, reject) => {
    timer = setTimeout(() => reject(new Error('database probe timed out')), timeoutMs);
    // do not let a pending probe hold the process open
    timer.unref();
  });

  try {
    // built inside the try so that even a synchronous throw from the client
    // returns false rather than escaping. this function must never reject - the
    // health route depends on always getting a boolean back.
    const probe = prisma.$queryRaw`SELECT 1`;
    // the probe can still reject after the deadline has already won the race,
    // and an unwatched rejection would crash the process
    probe.catch(() => undefined);

    await Promise.race([probe, deadline]);
    return true;
  } catch {
    return false;
  } finally {
    clearTimeout(timer);
  }
}

