      const toMask = field.needs.filter((prop) => omit[prop])
      if (toMask.length > 0) {
        maskingLayers.push(removeProperties(toMask))
      }
    } else if (select) {
      if (!select[field.name]) {
        continue
      }

      const toMask = field.needs.filter((prop) => !select[prop])
      if (toMask.length > 0) {
        maskingLayers.push(removeProperties(toMask))
      }
