export type BatchResponse = MultiBatchResponse | CompactedBatchResponse

export type MultiBatchResponse = {
  type: 'multi'
  plans: QueryPlanNode[]
}

export type CompactedBatchResponse = {
  type: 'compacted'
  plan: QueryPlanNode
  arguments: Record<string, {}>[]
  nestedSelection: string[]
