/**
 * Binary serialization for ParamGraph.
 *
 * This module handles compact binary encoding/decoding of the param graph structure.
 * The format uses a hybrid approach: JSON string array for field names + binary blob
 * for structural data (nodes, edges, roots).
 *
 * ## Serialized Representation
 *
 * ```
 * SerializedParamGraph {
 *   strings: string[]   // String table (field names, enum names, root keys)
 *   graph: string       // Base64url-encoded binary blob
 * }
 * ```
 *
 * ## Why Hybrid?
 *
 * - **Strings stay as JSON**: V8's JSON.parse is highly optimized for string arrays
 * - **Structure goes binary**: Indices, flags, masks benefit from compact encoding
 * - **Best of both**: Fast parsing + compact size where it matters
 *
 * ## Variable-Length Encoding
 *
 * All integer values (except fixed-size fields like `scalarMask` and `flags`) use
 * unsigned LEB128 (Little Endian Base 128) variable-length encoding:
 *
 * - Values 0-127: 1 byte
 * - Values 128-16383: 2 bytes
 * - Values 16384-2097151: 3 bytes
 * - And so on...
 *
 * Optional values use value+1 encoding: 0 means "none/undefined", N+1 means actual value N.
 *
 * ## Binary Blob Layout
 *
 * ```
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ HEADER                                                            │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ inputNodeCount: varuint                                           │
 * │ outputNodeCount: varuint                                          │
 * │ rootCount: varuint                                                │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ INPUT NODES (repeated inputNodeCount times)                       │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ edgeCount: varuint                                                │
 * │ edges[]                                                           │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ INPUT EDGE                                                        │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ fieldIndex: varuint                                               │
 * │ scalarMask: u16                                                   │
 * │ childNodeId: varuint (0=none, N+1=actual)                         │
 * │ enumNameIndex: varuint (0=none, N+1=actual)                       │
 * │ flags: u8                                                         │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ OUTPUT NODES (repeated outputNodeCount times)                     │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ edgeCount: varuint                                                │
 * │ edges[]                                                           │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ OUTPUT EDGE                                                       │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ fieldIndex: varuint                                               │
 * │ argsNodeId: varuint (0=none, N+1=actual)                          │
 * │ outputNodeId: varuint (0=none, N+1=actual)                        │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │ ROOTS (repeated rootCount times)                                  │
 * ├───────────────────────────────────────────────────────────────────┤
 * │ keyIndex: varuint                                                 │
 * │ argsNodeId: varuint (0=none, N+1=actual)                          │
 * │ outputNodeId: varuint (0=none, N+1=actual)                        │
 * └───────────────────────────────────────────────────────────────────┘
 * ```
 *
 * ## Embedding in Generated Client
 *
 * ```js
 * config.parameterizationSchema = {
 *   strings: JSON.parse('["where","id","email",...]'),
 *   graph: "base64url_encoded_binary_blob..."
 * }
 * ```
 */

import type {
  InputEdgeData,
  InputNodeData,
  OutputEdgeData,
  OutputNodeData,
  ParamGraphData,
  RootEntryData,
} from './types'

/**
 * Serialized format stored in the generated client.
 */
export interface SerializedParamGraph {
  /** String table (field names, enum names, root keys) */
  strings: string[]
  /** Base64url-encoded binary blob for structural data */
  graph: string
}

/**
 * Serializes a ParamGraphData to the compact binary format.
 */
export function serializeParamGraph(data: ParamGraphData): SerializedParamGraph {
  return new Serializer(data).serialize()
}

/**
 * Deserializes a binary-encoded ParamGraph.
 */
export function deserializeParamGraph(serialized: SerializedParamGraph): ParamGraphData {
  return new Deserializer(serialized).deserialize()
}

function encodeBase64url(bytes: Uint8Array): string {
  return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString('base64url')
}

function decodeBase64url(str: string): Uint8Array {
  return Buffer.from(str, 'base64url')
}

/**
 * Calculates the number of bytes needed to encode a value as an unsigned LEB128 varint.
 */
function varuintSize(value: number): number {
  let size = 1
  while (value >= 0x80) {
    size++
    value >>>= 7
  }
  return size
}

class Serializer {
  #data: ParamGraphData
  #buffer: ArrayBuffer
  #view: DataView
  #offset: number = 0
  #rootKeys: string[]

  constructor(data: ParamGraphData) {
    this.#data = data
    this.#rootKeys = Object.keys(data.roots)

    const size = this.#calculateBufferSize()
    this.#buffer = new ArrayBuffer(size)
    this.#view = new DataView(this.#buffer)
  }

  serialize(): SerializedParamGraph {
    this.#writeHeader()
    this.#writeInputNodes()
    this.#writeOutputNodes()
    this.#writeRoots()

    return {
      strings: this.#data.strings,
      graph: encodeBase64url(new Uint8Array(this.#buffer, 0, this.#offset)),
    }
  }

  #writeVaruint(value: number): void {
    while (value >= 0x80) {
      this.#view.setUint8(this.#offset++, (value & 0x7f) | 0x80)
      value >>>= 7
    }
    this.#view.setUint8(this.#offset++, value)
  }

  #writeOptionalVaruint(value: number | undefined): void {
    this.#writeVaruint(value === undefined ? 0 : value + 1)
  }

  #writeByte(value: number): void {
    this.#view.setUint8(this.#offset, value)
    this.#offset += 1
  }

  #writeU16(value: number): void {
    this.#view.setUint16(this.#offset, value, true)
    this.#offset += 2
  }

  #calculateBufferSize(): number {
    let size = 0

    // Header: 3 varints
    size += varuintSize(this.#data.inputNodes.length)
    size += varuintSize(this.#data.outputNodes.length)
    size += varuintSize(this.#rootKeys.length)

    for (const node of this.#data.inputNodes) {
      const fieldIndices = Object.keys(node.edges).map(Number)
      size += varuintSize(fieldIndices.length)

      for (const fieldIndex of fieldIndices) {
        const edge = node.edges[fieldIndex]
        size += varuintSize(fieldIndex)
        size += 2 // scalarMask: u16
        size += varuintSize(edge.childNodeId === undefined ? 0 : edge.childNodeId + 1)
        size += varuintSize(edge.enumNameIndex === undefined ? 0 : edge.enumNameIndex + 1)
        size += 1 // flags: u8
      }
    }

    for (const node of this.#data.outputNodes) {
      const fieldIndices = Object.keys(node.edges).map(Number)
      size += varuintSize(fieldIndices.length)

      for (const fieldIndex of fieldIndices) {
        const edge = node.edges[fieldIndex]
        size += varuintSize(fieldIndex)
        size += varuintSize(edge.argsNodeId === undefined ? 0 : edge.argsNodeId + 1)
        size += varuintSize(edge.outputNodeId === undefined ? 0 : edge.outputNodeId + 1)
      }
    }

    for (const key of this.#rootKeys) {
      const root = this.#data.roots[key]
      const keyIndex = this.#data.strings.indexOf(key)
      size += varuintSize(keyIndex)
      size += varuintSize(root.argsNodeId === undefined ? 0 : root.argsNodeId + 1)
      size += varuintSize(root.outputNodeId === undefined ? 0 : root.outputNodeId + 1)
    }

    return size
  }

  #writeHeader(): void {
    this.#writeVaruint(this.#data.inputNodes.length)
    this.#writeVaruint(this.#data.outputNodes.length)
    this.#writeVaruint(this.#rootKeys.length)
  }

  #writeInputNodes(): void {
    for (const node of this.#data.inputNodes) {
      const fieldIndices = Object.keys(node.edges).map(Number)
      this.#writeVaruint(fieldIndices.length)

      for (const fieldIndex of fieldIndices) {
        const edge = node.edges[fieldIndex]

        this.#writeVaruint(fieldIndex)
        this.#writeU16(edge.scalarMask ?? 0)
        this.#writeOptionalVaruint(edge.childNodeId)
        this.#writeOptionalVaruint(edge.enumNameIndex)
        this.#writeByte(edge.flags)
      }
    }
  }

  #writeOutputNodes(): void {
    for (const node of this.#data.outputNodes) {
      const fieldIndices = Object.keys(node.edges).map(Number)
      this.#writeVaruint(fieldIndices.length)

      for (const fieldIndex of fieldIndices) {
        const edge = node.edges[fieldIndex]

        this.#writeVaruint(fieldIndex)
        this.#writeOptionalVaruint(edge.argsNodeId)
        this.#writeOptionalVaruint(edge.outputNodeId)
      }
    }
  }

  #writeRoots(): void {
    for (const key of this.#rootKeys) {
      const root = this.#data.roots[key]
      const keyIndex = this.#data.strings.indexOf(key)
      if (keyIndex === -1) {
        throw new Error(`Root key "${key}" not found in strings table`)
      }

      this.#writeVaruint(keyIndex)
      this.#writeOptionalVaruint(root.argsNodeId)
      this.#writeOptionalVaruint(root.outputNodeId)
    }
  }
}

class Deserializer {
  #serialized: SerializedParamGraph
  #view: DataView
  #offset: number = 0

  constructor(serialized: SerializedParamGraph) {
    this.#serialized = serialized
    const bytes = decodeBase64url(serialized.graph)
    this.#view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  }

  deserialize(): ParamGraphData {
    const { inputNodeCount, outputNodeCount, rootCount } = this.#readHeader()
    const inputNodes = this.#readInputNodes(inputNodeCount)
    const outputNodes = this.#readOutputNodes(outputNodeCount)
    const roots = this.#readRoots(rootCount)

    return {
      strings: this.#serialized.strings,
      inputNodes,
      outputNodes,
      roots,
    }
  }

  #readVaruint(): number {
    let value = 0
    let shift = 0
    let byte: number
    do {
      byte = this.#view.getUint8(this.#offset++)
      value |= (byte & 0x7f) << shift
      shift += 7
    } while (byte >= 0x80)
    return value
  }

  #readOptionalVaruint(): number | undefined {
    const value = this.#readVaruint()
    return value === 0 ? undefined : value - 1
  }

  #readByte(): number {
    const value = this.#view.getUint8(this.#offset)
    this.#offset += 1
    return value
  }

  #readU16(): number {
    const value = this.#view.getUint16(this.#offset, true)
    this.#offset += 2
    return value
  }

  #readHeader(): { inputNodeCount: number; outputNodeCount: number; rootCount: number } {
    const inputNodeCount = this.#readVaruint()
    const outputNodeCount = this.#readVaruint()
    const rootCount = this.#readVaruint()

    return { inputNodeCount, outputNodeCount, rootCount }
  }

  #readInputNodes(count: number): InputNodeData[] {
    const inputNodes: InputNodeData[] = []

    for (let i = 0; i < count; i++) {
      const edgeCount = this.#readVaruint()
      const edges: Record<number, InputEdgeData> = {}

      for (let j = 0; j < edgeCount; j++) {
        const fieldIndex = this.#readVaruint()
        const scalarMask = this.#readU16()
        const childNodeId = this.#readOptionalVaruint()
        const enumNameIndex = this.#readOptionalVaruint()
        const flags = this.#readByte()

        const edge: InputEdgeData = { flags }
        if (scalarMask !== 0) edge.scalarMask = scalarMask
        if (childNodeId !== undefined) edge.childNodeId = childNodeId
        if (enumNameIndex !== undefined) edge.enumNameIndex = enumNameIndex

        edges[fieldIndex] = edge
      }

      inputNodes.push({ edges })
    }

    return inputNodes
  }

  #readOutputNodes(count: number): OutputNodeData[] {
    const outputNodes: OutputNodeData[] = []

    for (let i = 0; i < count; i++) {
      const edgeCount = this.#readVaruint()
      const edges: Record<number, OutputEdgeData> = {}

      for (let j = 0; j < edgeCount; j++) {
        const fieldIndex = this.#readVaruint()
        const argsNodeId = this.#readOptionalVaruint()
        const outputNodeId = this.#readOptionalVaruint()

        const edge: OutputEdgeData = {}
        if (argsNodeId !== undefined) edge.argsNodeId = argsNodeId
        if (outputNodeId !== undefined) edge.outputNodeId = outputNodeId

        edges[fieldIndex] = edge
      }

      outputNodes.push({ edges })
    }

    return outputNodes
  }

  #readRoots(count: number): Record<string, RootEntryData> {
    const roots: Record<string, RootEntryData> = {}

    for (let i = 0; i < count; i++) {
      const keyIndex = this.#readVaruint()
      const argsNodeId = this.#readOptionalVaruint()
      const outputNodeId = this.#readOptionalVaruint()

      const key = this.#serialized.strings[keyIndex]
      const root: RootEntryData = {}
      if (argsNodeId !== undefined) root.argsNodeId = argsNodeId
      if (outputNodeId !== undefined) root.outputNodeId = outputNodeId

      roots[key] = root
    }

    return roots
  }
}
/**
 * ParamGraph: Runtime class for schema-aware parameterization.
 *
 * This class provides a readable API for navigating the param graph structure
 * at runtime. It's created once per PrismaClient instance from the serialized
 * format embedded in the generated client.
 */

import type { SerializedParamGraph } from './serialization'
import { deserializeParamGraph } from './serialization'
import type {
  InputEdgeData,
  InputNodeData,
  OutputEdgeData,
  OutputNodeData,
  ParamGraphData,
  RootEntryData,
} from './types'

/**
 * Map of enum names to their respective values.
 */
export type EnumNameToValueMap = Record<string, string>

/**
 * Function type for looking up enum values by name.
 * This allows ParamGraph to remain decoupled from RuntimeDataModel.
 */
export type EnumLookup = (enumName: string) => Readonly<EnumNameToValueMap> | undefined

/**
 * Readable view of root entry.
 */
export interface RootEntry {
  readonly argsNodeId: number | undefined
  readonly outputNodeId: number | undefined
}

/**
 * Readable view of input node.
 */
export interface InputNode {
  readonly id: number
}

/**
 * Readable view of output node.
 */
export interface OutputNode {
  readonly id: number
}

/**
 * Readable view of input edge.
 */
export interface InputEdge {
  readonly flags: number
  readonly childNodeId: number | undefined
  readonly scalarMask: number
  readonly enumNameIndex: number | undefined
}

/**
 * Readable view of output edge.
 */
export interface OutputEdge {
  readonly argsNodeId: number | undefined
  readonly outputNodeId: number | undefined
}

/**
 * ParamGraph provides runtime access to the schema information
 * needed for parameterization decisions.
 */
export class ParamGraph {
  readonly #data: ParamGraphData
  readonly #stringIndex: Map<string, number>
  readonly #enumLookup: EnumLookup

  private constructor(data: ParamGraphData, enumLookup: EnumLookup) {
    this.#data = data
    this.#enumLookup = enumLookup

    // Build string-to-index map for O(1) lookups
    this.#stringIndex = new Map<string, number>()
    for (let i = 0; i < data.strings.length; i++) {
      this.#stringIndex.set(data.strings[i], i)
    }
  }

  /**
   * Creates a ParamGraph from serialized format.
   * This is the primary factory method for runtime use.
   */
  static deserialize(serialized: SerializedParamGraph, enumLookup: EnumLookup): ParamGraph {
    const data = deserializeParamGraph(serialized)
    return new ParamGraph(data, enumLookup)
  }

  /**
   * Creates a ParamGraph from builder data.
   * Used by the builder for testing and direct construction.
   */
  static fromData(data: ParamGraphData, enumLookup: EnumLookup): ParamGraph {
    return new ParamGraph(data, enumLookup)
  }

  /**
   * Look up a root entry by "Model.action" or "action".
   */
  root(key: string): RootEntry | undefined {
    const entry = this.#data.roots[key]
    if (!entry) {
      return undefined
    }
    return {
      argsNodeId: entry.argsNodeId,
      outputNodeId: entry.outputNodeId,
    }
  }

  /**
   * Get an input node by ID.
   */
  inputNode(id: number | undefined): InputNode | undefined {
    if (id === undefined || id < 0 || id >= this.#data.inputNodes.length) {
      return undefined
    }
    return { id }
  }

  /**
   * Get an output node by ID.
   */
  outputNode(id: number | undefined): OutputNode | undefined {
    if (id === undefined || id < 0 || id >= this.#data.outputNodes.length) {
      return undefined
    }
    return { id }
  }

  /**
   * Get an input edge for a field name within a node.
   */
  inputEdge(node: InputNode | undefined, fieldName: string): InputEdge | undefined {
    if (!node) {
      return undefined
    }

    const nodeData = this.#data.inputNodes[node.id]
    if (!nodeData) {
      return undefined
    }

    const fieldIndex = this.#stringIndex.get(fieldName)
    if (fieldIndex === undefined) {
      return undefined
    }

    const edge = nodeData.edges[fieldIndex]
    if (!edge) {
      return undefined
    }

    return {
      flags: edge.flags,
      childNodeId: edge.childNodeId,
      scalarMask: edge.scalarMask ?? 0,
      enumNameIndex: edge.enumNameIndex,
    }
  }

  /**
   * Get an output edge for a field name within a node.
   */
  outputEdge(node: OutputNode | undefined, fieldName: string): OutputEdge | undefined {
    if (!node) {
      return undefined
    }

    const nodeData = this.#data.outputNodes[node.id]
    if (!nodeData) {
      return undefined
    }

    const fieldIndex = this.#stringIndex.get(fieldName)
    if (fieldIndex === undefined) {
      return undefined
    }

    const edge = nodeData.edges[fieldIndex]
    if (!edge) {
      return undefined
    }

    return {
      argsNodeId: edge.argsNodeId,
      outputNodeId: edge.outputNodeId,
    }
  }

  /**
   * Get enum values for an edge that references a user enum.
   * Returns undefined if the edge doesn't reference an enum.
   */
  enumValues(edge: InputEdge | undefined): Readonly<EnumNameToValueMap> | undefined {
    if (edge?.enumNameIndex === undefined) {
      return undefined
    }

    const enumName = this.#data.strings[edge.enumNameIndex]
    if (!enumName) {
      return undefined
    }

    return this.#enumLookup(enumName)
  }

  /**
   * Get a string from the string table by index.
   */
  getString(index: number): string | undefined {
    return this.#data.strings[index]
  }
}

/**
 * Bit flags for InputEdge.flags describing what the field accepts.
 */
export const EdgeFlag = {
  /**
   * Field may be parameterized as a scalar value.
   * Check ScalarMask to validate the value type.
   */
  ParamScalar: 1,

  /**
   * Field may be parameterized as an enum.
   * Check enum ID to validate the value type.
   */
  ParamEnum: 2,

  /**
   * Field accepts list-of-scalar values.
   * Parameterize the whole list if all elements match ScalarMask.
   */
  ParamListScalar: 4,

  /**
   * Field accepts list-of-enum values.
   * Parameterize the whole list if all elements match enum ID.
   */
  ParamListEnum: 8,

  /**
   * Field accepts list-of-object values.
   * Recurse into each element using the child node.
   */
  ListObject: 16,

  /**
   * Field accepts object values.
   * Recurse into child input node.
   */
  Object: 32,
} as const

export type EdgeFlagValue = (typeof EdgeFlag)[keyof typeof EdgeFlag]

/**
 * Bit mask for scalar type categories.
 * Used in InputEdge.scalarMask to validate runtime value types.
 */
export const ScalarMask = {
  String: 1,
  Int: 2,
  BigInt: 4,
  Float: 8,
  Decimal: 16,
  Boolean: 32,
  DateTime: 64,
  Json: 128,
  Bytes: 256,
} as const

export type ScalarMaskValue = (typeof ScalarMask)[keyof typeof ScalarMask]

/**
 * Helper function to check if an edge has a specific flag.
 */
export function hasFlag(edge: InputEdge, flag: number): boolean {
  return (edge.flags & flag) !== 0
}

/**
 * Helper function to get the scalar mask from an edge.
 */
export function getScalarMask(edge: InputEdge): number {
  return edge.scalarMask
}

/**
 * Maps DMMF scalar type names to ScalarMask values.
 */
export function scalarTypeToMask(typeName: string): number {
  switch (typeName) {
    case 'String':
    case 'UUID':
      return ScalarMask.String
    case 'Int':
      return ScalarMask.Int
    case 'BigInt':
      return ScalarMask.BigInt
    case 'Float':
      return ScalarMask.Float
    case 'Decimal':
      return ScalarMask.Decimal
    case 'Boolean':
      return ScalarMask.Boolean
    case 'DateTime':
      return ScalarMask.DateTime
    case 'Json':
      return ScalarMask.Json
    case 'Bytes':
      return ScalarMask.Bytes
    default:
      return 0
  }
}

// Re-export data types for builder use
export type { InputEdgeData, InputNodeData, OutputEdgeData, OutputNodeData, ParamGraphData, RootEntryData }
/**
 * Value classification for parameterization.
 *
 * This module classifies runtime values into categories before applying
 * schema rules during parameterization.
 */

import { JsonInputTaggedValue } from '@prisma/json-protocol'

/**
 * Tagged value types that represent scalar values.
 * These can be parameterized when the schema allows.
 */
const SCALAR_TAGS = new Set(['DateTime', 'Decimal', 'BigInt', 'Bytes', 'Json', 'Raw'])

/**
 * Classification result for a runtime value.
 * Used to determine how to handle the value during parameterization.
 */
export type ValueClass =
  | { kind: 'null' }
  | { kind: 'primitive'; value: string | number | boolean }
  | { kind: 'taggedScalar'; tag: JsonInputTaggedValue['$type']; value: unknown }
  | { kind: 'structural'; value: unknown }
  | { kind: 'array'; items: unknown[] }
  | { kind: 'object'; entries: Record<string, unknown> }

/**
 * Classifies a runtime value for parameterization purposes.
 *
 * @param value - The value to classify
 * @returns The classification result indicating how to handle the value
 */
export function classifyValue(value: unknown): ValueClass {
  if (value === null || value === undefined) {
    return { kind: 'null' }
  }

  if (typeof value === 'string') {
    return { kind: 'primitive', value }
  }
  if (typeof value === 'number') {
    return { kind: 'primitive', value }
  }
  if (typeof value === 'boolean') {
    return { kind: 'primitive', value }
  }

  if (Array.isArray(value)) {
    return { kind: 'array', items: value }
  }

  if (typeof value === 'object') {
    const obj = value as Record<string, unknown>

    if ('$type' in obj && typeof obj.$type === 'string') {
      const tag = obj.$type as JsonInputTaggedValue['$type']

      if (SCALAR_TAGS.has(tag)) {
        return { kind: 'taggedScalar', tag, value: obj.value }
      }

      // Known structural tags and any unknown $type tags are treated as structural
      // to avoid parameterizing tagged payloads that we don't understand.
      return { kind: 'structural', value: obj.value }
    }

    return { kind: 'object', entries: obj }
  }

  return { kind: 'structural', value }
}

/**
 * Checks if a value is a plain object (not a tagged value or array).
 */
export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    !('$type' in (value as Record<string, unknown>))
  )
}

/**
 * Checks if a value is a tagged value with a $type property.
 */
export function isTaggedValue(value: unknown): value is { $type: string; value: unknown } {
  return (
    typeof value === 'object' &&
    value !== null &&
    '$type' in value &&
    typeof (value as { $type: unknown }).$type === 'string'
  )
}
/**
 * Schema-aware traversal algorithm for parameterization.
 *
 * This module implements the core parameterization logic that walks the
 * JsonQuery tree guided by ParamGraph. It only parameterizes values when
 * both schema rules and runtime value types agree.
 */

import type {
  JsonArgumentValue,
  JsonBatchQuery,
  JsonFieldSelection,
  JsonInputTaggedValue,
  JsonQuery,
  JsonSelectionSet,
  PlaceholderTaggedValue,
} from '@prisma/json-protocol'
import { PlaceholderType } from '@prisma/json-protocol'
import type { InputEdge, InputNode } from '@prisma/param-graph'
import { EdgeFlag, getScalarMask, hasFlag, ParamGraph, ScalarMask } from '@prisma/param-graph'

import { deserializeJsonObject } from '../json-protocol'
import { safeJsonStringify } from '../utils'
import { classifyValue, isPlainObject, isTaggedValue, ValueClass } from './classify'

/**
 * Result of parameterizing a single query.
 */
export interface ParameterizeResult {
  /** The query with user data values replaced by placeholders */
  parameterizedQuery: JsonQuery
  /** Map of placeholder names to their actual values */
  placeholderValues: Record<string, unknown>
}

/**
 * Result of parameterizing a batch of queries.
 */
export interface ParameterizeBatchResult {
  /** The batch with user data values replaced by placeholders */
  parameterizedBatch: JsonBatchQuery
  /** Combined map of placeholder names to their actual values */
  placeholderValues: Record<string, unknown>
}

/**
 * Parameterizes a single query using the schema-aware approach.
 *
 * @param query - The query to parameterize
 * @param view - The ParamGraph for schema lookups
 * @returns The parameterized query with extracted placeholder values
 */
export function parameterizeQuery(query: JsonQuery, view: ParamGraph): ParameterizeResult {
  const parameterizer = new Parameterizer(view)

  const rootKey = query.modelName ? `${query.modelName}.${query.action}` : query.action
  const root = view.root(rootKey)

  const parameterizedQuery: JsonQuery = {
    ...query,
    query: parameterizer.parameterizeFieldSelection(query.query, root?.argsNodeId, root?.outputNodeId),
  }

  return {
    parameterizedQuery,
    placeholderValues: parameterizer.getPlaceholderValues(),
  }
}

/**
 * Parameterizes a batch of queries using the schema-aware approach.
 *
 * @param batch - The batch to parameterize
 * @param view - The ParamGraph for schema lookups
 * @returns The parameterized batch with extracted placeholder values
 */
export function parameterizeBatch(batch: JsonBatchQuery, view: ParamGraph): ParameterizeBatchResult {
  const parameterizer = new Parameterizer(view)
  const parameterizedQueries: JsonQuery[] = []

  for (let i = 0; i < batch.batch.length; i++) {
    const query = batch.batch[i]

    const rootKey = query.modelName ? `${query.modelName}.${query.action}` : query.action
    const root = view.root(rootKey)

    parameterizedQueries.push({
      ...query,
      query: parameterizer.parameterizeFieldSelection(query.query, root?.argsNodeId, root?.outputNodeId),
    })
  }

  return {
    parameterizedBatch: { ...batch, batch: parameterizedQueries },
    placeholderValues: parameterizer.getPlaceholderValues(),
  }
}

/**
 * Encapsulates the state and logic for parameterizing queries.
 */
class Parameterizer {
  readonly #view: ParamGraph
  readonly #placeholders = new Map<string, unknown>()
  readonly #valueToPlaceholder = new Map<string, string>()
  #nextPlaceholderId = 1

  constructor(view: ParamGraph) {
    this.#view = view
  }

  /**
   * Returns the collected placeholder values as a plain object.
   */
  getPlaceholderValues(): Record<string, unknown> {
    return Object.fromEntries(this.#placeholders)
  }

  /**
   * Gets or creates a placeholder for the given value.
   * If a placeholder already exists for this value, returns a reference to the existing name.
   * Otherwise, registers a new placeholder with a sequential name.
   * We reuse the placeholders for equal values because the query compiler needs to be able
   * to compare the values for equality for certain optimizations (at the time of writing,
   * only for deciding whether to use native or emulated upserts).
   */
  #getOrCreatePlaceholder(value: unknown, type: PlaceholderType): PlaceholderTaggedValue {
    const valueKey = createValueKey(value, type)
    const existingName = this.#valueToPlaceholder.get(valueKey)

    if (existingName !== undefined) {
      return createPlaceholder(existingName, type)
    }

    const name = `%${this.#nextPlaceholderId++}`
    this.#valueToPlaceholder.set(valueKey, name)
    this.#placeholders.set(name, value)
    return createPlaceholder(name, type)
  }

  /**
   * Parameterizes a field selection (arguments + selection).
   */
  parameterizeFieldSelection(
    sel: JsonFieldSelection,
    argsNodeId: number | undefined,
    outNodeId: number | undefined,
  ): JsonFieldSelection {
    const argsNode = this.#view.inputNode(argsNodeId)
    const outNode = this.#view.outputNode(outNodeId)

    const result: JsonFieldSelection = { ...sel }

    if (sel.arguments && sel.arguments.$type !== 'Raw') {
      result.arguments = this.#parameterizeObject(sel.arguments as Record<string, unknown>, argsNode)
    }

    if (sel.selection) {
      result.selection = this.#parameterizeSelection(sel.selection, outNode)
    }

    return result
  }

  /**
   * Parameterizes an object by traversing its fields with the input node.
   */
  #parameterizeObject(obj: Record<string, unknown>, node: InputNode | undefined): Record<string, JsonArgumentValue> {
    if (!node) {
      // No parameterizable fields in this subtree - return as-is
      return obj as Record<string, JsonArgumentValue>
    }

    const result: Record<string, JsonArgumentValue> = {}

    for (const [key, value] of Object.entries(obj)) {
      const edge = this.#view.inputEdge(node, key)

      if (edge) {
        result[key] = this.#parameterizeValue(value, edge) as JsonArgumentValue
      } else {
        result[key] = value as JsonArgumentValue
      }
    }

    return result
  }

  /**
   * Core parameterization logic for a single value.
   */
  #parameterizeValue(value: unknown, edge: InputEdge): unknown {
    const classified = classifyValue(value)

    switch (classified.kind) {
      case 'null':
        // Null values are never parameterized - they affect query semantics
        return value

      case 'structural':
        return value

      case 'primitive':
        return this.#handlePrimitive(classified.value, edge)

      case 'taggedScalar':
        return this.#handleTaggedScalar(value as JsonInputTaggedValue, classified.tag, edge)

      case 'array':
        return this.#handleArray(classified.items, value, edge)

      case 'object':
        return this.#handleObject(classified.entries, edge)

      default:
        throw new Error(`Unknown value kind ${(classified satisfies never as ValueClass).kind}`)
    }
  }

  /**
   * Handles parameterization of primitive values (string, number, boolean).
   */
  #handlePrimitive(value: string | number | boolean, edge: InputEdge): JsonArgumentValue {
    if (hasFlag(edge, EdgeFlag.ParamEnum) && edge.enumNameIndex !== undefined && typeof value === 'string') {
      const enumValues = this.#view.enumValues(edge)
      if (enumValues && Object.hasOwn(enumValues, value)) {
        const type: PlaceholderType = { type: 'Enum' }
        return this.#getOrCreatePlaceholder(enumValues[value], type)
      }
    }

    if (!hasFlag(edge, EdgeFlag.ParamScalar)) {
      return value
    }

    const mask = getScalarMask(edge)
    if (mask === 0) {
      return value
    }

    const type = getPrimitivePlaceholderType(value)
    if (!matchesPrimitiveMask(type, mask)) {
      return value
    }

    if (mask & ScalarMask.Json) {
      value = JSON.stringify(value)
    }

    return this.#getOrCreatePlaceholder(value, type)
  }

  /**
   * Handles parameterization of tagged scalar values (DateTime, Decimal, etc.).
   */
  #handleTaggedScalar(tagged: JsonInputTaggedValue, tag: JsonInputTaggedValue['$type'], edge: InputEdge): unknown {
    if (!hasFlag(edge, EdgeFlag.ParamScalar)) {
      return tagged
    }

    const mask = getScalarMask(edge)
    if (mask === 0 || !matchesTaggedMask(tag, mask)) {
      return tagged
    }

    const type = getTaggedPlaceholderType(tagged.$type)!
    const decoded = decodeTaggedValue(tagged)

    return this.#getOrCreatePlaceholder(decoded, type)
  }

  /**
   * Handles parameterization of array values.
   */
  #handleArray(items: unknown[], originalValue: unknown, edge: InputEdge): unknown {
    if (hasFlag(edge, EdgeFlag.ParamScalar) && getScalarMask(edge) & ScalarMask.Json) {
      const jsonValue = safeJsonStringify(deserializeJsonObject(items))
      const type: PlaceholderType = { type: 'Json' }
      return this.#getOrCreatePlaceholder(jsonValue, type)
    }

    if (hasFlag(edge, EdgeFlag.ParamEnum)) {
      const enumValues = this.#view.enumValues(edge)
      if (enumValues && items.every((item) => typeof item === 'string' && Object.hasOwn(enumValues, item))) {
        const type: PlaceholderType = { type: 'List', inner: { type: 'Enum' } }
        return this.#getOrCreatePlaceholder(items, type)
      }
    }

    if (hasFlag(edge, EdgeFlag.ParamListScalar)) {
      const allValid = items.every((item) => validateListElement(item, edge))
      if (allValid && items.length > 0) {
        const decodedItems = items.map((item) => decodeIfTagged(item))
        const innerType = inferListElementType(items)
        const type: PlaceholderType = { type: 'List', inner: innerType }
        return this.#getOrCreatePlaceholder(decodedItems, type)
      }
    }

    if (hasFlag(edge, EdgeFlag.ListObject)) {
      const childNode = this.#view.inputNode(edge.childNodeId)
      if (childNode) {
        return items.map((item) => {
          if (isPlainObject(item)) {
            return this.#parameterizeObject(item, childNode)
          }
          return item
        })
      }
    }

    return originalValue
  }

  /**
   * Handles parameterization of object values.
   */
  #handleObject(obj: Record<string, unknown>, edge: InputEdge): unknown {
    if (hasFlag(edge, EdgeFlag.Object)) {
      const childNode = this.#view.inputNode(edge.childNodeId)
      if (childNode) {
        return this.#parameterizeObject(obj, childNode)
      }
    }

    const mask = getScalarMask(edge)
    if (mask & ScalarMask.Json) {
      const jsonValue = safeJsonStringify(deserializeJsonObject(obj))
      const type: PlaceholderType = { type: 'Json' }
      return this.#getOrCreatePlaceholder(jsonValue, type)
    }

    return obj
  }

  /**
   * Parameterizes a selection set using output nodes.
   */
  #parameterizeSelection(selection: JsonSelectionSet, node: ReturnType<ParamGraph['outputNode']>): JsonSelectionSet {
    if (!selection || !node) {
      return selection
    }

    const result: JsonSelectionSet = {}

    for (const [key, value] of Object.entries(selection)) {
      if (key === '$scalars' || key === '$composites' || typeof value === 'boolean') {
        result[key] = value
        continue
      }

      const edge = this.#view.outputEdge(node, key)

      if (edge) {
        // Nested selection with possible args
        const nested = value as { arguments?: Record<string, unknown>; selection?: JsonSelectionSet }

        const argsNode = this.#view.inputNode(edge.argsNodeId)
        const childOutNode = this.#view.outputNode(edge.outputNodeId)

        const processedValue: JsonFieldSelection = {
          selection: nested.selection ? this.#parameterizeSelection(nested.selection, childOutNode) : {},
        }

        if (nested.arguments) {
          processedValue.arguments = this.#parameterizeObject(nested.arguments, argsNode)
        }

        result[key] = processedValue
      } else {
        result[key] = value
      }
    }

    return result
  }
}

/**
 * Creates a placeholder object with the given name.
 */
function createPlaceholder(name: string, type: PlaceholderType): PlaceholderTaggedValue {
  return { $type: 'Param', value: { name, ...type } }
}

/**
 * Serializes a PlaceholderType to a string for use as part of a value key.
 */
function serializePlaceholderType(type: PlaceholderType): string {
  if (type.type === 'List') {
    return `List<${serializePlaceholderType(type.inner)}>`
  }
  return type.type
}

/**
 * Serializes a value to a string for use as part of a value key.
 */
function serializeValue(value: unknown): string {
  if (ArrayBuffer.isView(value)) {
    const bufView = Buffer.from(value.buffer, value.byteOffset, value.byteLength)
    return bufView.toString('base64')
  }
  return JSON.stringify(value)
}

/**
 * Creates a unique key for a (value, type) pair.
 * Used to detect when the same value appears multiple times.
 */
function createValueKey(value: unknown, type: PlaceholderType): string {
  const typeKey = serializePlaceholderType(type)
  const valueKey = serializeValue(value)
  return `${typeKey}:${valueKey}`
}

const MAX_INT = 2 ** 31 - 1
const MIN_INT = -(2 ** 31)

function getPrimitivePlaceholderType(value: string | number | boolean): PlaceholderType {
  switch (typeof value) {
    case 'boolean':
      return { type: 'Boolean' }

    case 'number':
      if (!Number.isInteger(value)) {
        return { type: 'Float' }
      }
      if (MIN_INT <= value && value <= MAX_INT) {
        return { type: 'Int' }
      }
      return { type: 'BigInt' }

    case 'string':
      return { type: 'String' }

    default:
      throw new Error('unreachable')
  }
}

/**
 * Checks if a primitive value matches the scalar mask.
 */
function matchesPrimitiveMask({ type }: PlaceholderType, mask: number): boolean {
  switch (type) {
    case 'Boolean':
      return (mask & ScalarMask.Boolean) !== 0
    case 'Int':
      return (mask & (ScalarMask.Int | ScalarMask.BigInt | ScalarMask.Float)) !== 0
    case 'BigInt':
      return (mask & ScalarMask.BigInt) !== 0
    case 'Float':
      return (mask & ScalarMask.Float) !== 0
    case 'String':
      return (mask & ScalarMask.String) !== 0
    default:
      return false
  }
}

function getTaggedPlaceholderType(tag: JsonInputTaggedValue['$type']): PlaceholderType | undefined {
  switch (tag) {
    case 'BigInt':
    case 'Bytes':
    case 'DateTime':
    case 'Json':
      return { type: tag }
    case 'Decimal':
      // PrismaValueType doesn't have a Decimal variant and treats both Floats
      // and Decimal as decimals
      return { type: 'Float' }
    default:
      return undefined
  }
}

/**
 * Infers the widest placeholder type that accommodates all elements in a list.
 * For example, a list containing both Int and Float values infers Float.
 */
function inferListElementType(items: unknown[]): PlaceholderType {
  let widest: PlaceholderType = { type: 'Any' }

  for (const item of items) {
    const classified = classifyValue(item)
    let itemType: PlaceholderType

    switch (classified.kind) {
      case 'primitive':
        itemType = getPrimitivePlaceholderType(classified.value)
        break
      case 'taggedScalar':
        itemType = getTaggedPlaceholderType(classified.tag) ?? { type: 'Any' }
        break
      default:
        return { type: 'Any' }
    }

    widest = widenType(widest, itemType)
  }

  return widest
}

/**
 * Returns the wider of two placeholder types, following numeric promotion rules:
 * Int -> BigInt -> Float. Non-numeric types must match exactly or produce Any.
 */
function widenType(a: PlaceholderType, b: PlaceholderType): PlaceholderType {
  if (a.type === 'Any') return b
  if (b.type === 'Any') return a
  if (a.type === b.type) return a

  const NUMERIC_WIDTH: Partial<Record<PlaceholderType['type'], number>> = { Int: 0, BigInt: 1, Float: 2 }
  const aWidth = NUMERIC_WIDTH[a.type]
  const bWidth = NUMERIC_WIDTH[b.type]

  if (aWidth !== undefined && bWidth !== undefined) {
    return aWidth >= bWidth ? a : b
  }

  return { type: 'Any' }
}

/**
 * Checks if a tagged scalar tag matches the scalar mask.
 */
function matchesTaggedMask(tag: JsonInputTaggedValue['$type'], mask: number): boolean {
  switch (tag) {
    case 'DateTime':
      return (mask & ScalarMask.DateTime) !== 0
    case 'Decimal':
      return (mask & ScalarMask.Decimal) !== 0
    case 'BigInt':
      return (mask & ScalarMask.BigInt) !== 0
    case 'Bytes':
      return (mask & ScalarMask.Bytes) !== 0
    case 'Json':
      return (mask & ScalarMask.Json) !== 0
    default:
      return false
  }
}

/**
 * Validates that a list element can be parameterized.
 */
function validateListElement(item: unknown, edge: InputEdge): boolean {
  const classified = classifyValue(item)

  switch (classified.kind) {
    case 'structural':
      return false

    case 'null':
      return false

    case 'primitive': {
      const type = getPrimitivePlaceholderType(classified.value)
      const mask = getScalarMask(edge)
      return mask !== 0 && matchesPrimitiveMask(type, mask)
    }

    case 'taggedScalar': {
      const mask = getScalarMask(edge)
      return mask !== 0 && matchesTaggedMask(classified.tag, mask)
    }

    default:
      return false
  }
}

/**
 * Decodes a value if it's a tagged scalar, otherwise returns as-is.
 */
function decodeIfTagged(value: unknown): unknown {
  if (isTaggedValue(value)) {
    return decodeTaggedValue(value)
  }
  return value
}

/**
 * Decodes a tagged scalar value to its raw form.
 */
function decodeTaggedValue(tagged: { $type: string; value: unknown }): unknown {
  return tagged.value
}
type Crypto = {
  randomUUID: () => string
}

async function getCrypto(): Promise<Crypto> {
  // TODO: always use `globalThis.crypto` when we drop Node.js 18 support
  return globalThis.crypto ?? (await import('node:crypto'))
}

export async function randomUUID(): Promise<string> {
  const crypto = await getCrypto()
  return crypto.randomUUID()
}
/**
 * Equivalent to `once` from `node:events` for DOM {@link EventTarget}.
 *
 * It is useful, e.g., to wait for an `abort` event on {@link AbortSignal}.
 * While in Node.js `AbortSignal` does implement `EventEmitter` interface
 * and is compatible with the `once` utility in `node:events`, it is not
 * necessarily the case in other JS runtimes.
 */
export async function once(target: EventTarget, event: string): Promise<Event> {
  return new Promise((resolve) => {
    target.addEventListener(event, resolve, { once: true })
  })
}
import { UserFacingError } from '../user-facing-error'

export class TransactionManagerError extends UserFacingError {
  name = 'TransactionManagerError'

  constructor(message: string, meta?: Record<string, unknown>) {
    super('Transaction API error: ' + message, 'P2028', meta)
  }
}

export class TransactionNotFoundError extends TransactionManagerError {
  constructor() {
    super(
      "Transaction not found. Transaction ID is invalid, refers to an old closed transaction Prisma doesn't have information about anymore, or was obtained before disconnecting.",
    )
  }
}

export class TransactionClosedError extends TransactionManagerError {
  constructor(operation: string) {
    super(`Transaction already closed: A ${operation} cannot be executed on a committed transaction.`)
  }
}

export class TransactionRolledBackError extends TransactionManagerError {
  constructor(operation: string) {
    super(`Transaction already closed: A ${operation} cannot be executed on a transaction that was rolled back.`)
  }
}

export class TransactionStartTimeoutError extends TransactionManagerError {
  constructor() {
    super('Unable to start a transaction in the given time.')
  }
}

export class TransactionExecutionTimeoutError extends TransactionManagerError {
  constructor(operation: string, { timeout, timeTaken }: { timeout: number; timeTaken: number }) {
    super(
      `A ${operation} cannot be executed on an expired transaction. \
The timeout for this transaction was ${timeout} ms, however ${timeTaken} ms passed since the start \
of the transaction. Consider increasing the interactive transaction timeout \
or doing less work in the transaction.`,
      { operation, timeout, timeTaken },
    )
  }
}

export class TransactionInternalConsistencyError extends TransactionManagerError {
  constructor(message: string) {
    super(`Internal Consistency Error: ${message}`)
  }
}

export class InvalidTransactionIsolationLevelError extends TransactionManagerError {
  constructor(isolationLevel: string) {
    super(`Invalid isolation level: ${isolationLevel}`, { isolationLevel })
  }
}
import { Debug } from '@prisma/debug'
import { SqlDriverAdapter, SqlQuery, SqlQueryable, Transaction } from '@prisma/driver-adapter-utils'

import { randomUUID } from '../crypto'
import { QueryEvent } from '../events'
import type { SchemaProvider } from '../schema'
import { TracingHelper, withQuerySpanAndEvent } from '../tracing'
import { rethrowAsUserFacing } from '../user-facing-error'
import { assertNever } from '../utils'
import { once } from '../web-platform'
import { Options, TransactionInfo } from './transaction'
import {
  InvalidTransactionIsolationLevelError,
  TransactionClosedError,
  TransactionExecutionTimeoutError,
  TransactionInternalConsistencyError,
  TransactionManagerError,
  TransactionNotFoundError,
  TransactionRolledBackError,
  TransactionStartTimeoutError,
} from './transaction-manager-error'

const MAX_CLOSED_TRANSACTIONS = 100

type TransactionWrapper = {
  id: string
  timer?: NodeJS.Timeout
  timeout: number | undefined
  startedAt: number
  transaction?: Transaction
  operationQueue: Promise<void>
  depth: number
  savepoints: string[]
  savepointCounter: number
} & TransactionState

type TransactionState =
  | { status: 'waiting' | 'running' | 'committed' | 'rolled_back' | 'timed_out' }
  | { status: 'closing'; closing: Promise<void>; reason: 'committed' | 'rolled_back' | 'timed_out' }

const debug = Debug('prisma:client:transactionManager')

const COMMIT_QUERY = (): SqlQuery => ({ sql: 'COMMIT', args: [], argTypes: [] })
const ROLLBACK_QUERY = (): SqlQuery => ({ sql: 'ROLLBACK', args: [], argTypes: [] })

const PHANTOM_COMMIT_QUERY = (): SqlQuery => ({
  sql: '-- Implicit "COMMIT" query via underlying driver',
  args: [],
  argTypes: [],
})
const PHANTOM_ROLLBACK_QUERY = (): SqlQuery => ({
  sql: '-- Implicit "ROLLBACK" query via underlying driver',
  args: [],
  argTypes: [],
})

export class TransactionManager {
  // The map of active transactions.
  private transactions: Map<string, TransactionWrapper> = new Map()
  // List of last closed transactions. Max MAX_CLOSED_TRANSACTIONS entries.
  // Used to provide better error messages than a generic "transaction not found".
  private closedTransactions: TransactionWrapper[] = []
  private readonly driverAdapter: SqlDriverAdapter
  private readonly transactionOptions: Options
  private readonly tracingHelper: TracingHelper
  readonly #onQuery?: (event: QueryEvent) => void
  readonly #provider?: SchemaProvider

  constructor({
    driverAdapter,
    transactionOptions,
    tracingHelper,
    onQuery,
    provider,
  }: {
    driverAdapter: SqlDriverAdapter
    transactionOptions: Options
    tracingHelper: TracingHelper
    onQuery?: (event: QueryEvent) => void
    provider?: SchemaProvider
  }) {
    this.driverAdapter = driverAdapter
    this.transactionOptions = transactionOptions
    this.tracingHelper = tracingHelper
    this.#onQuery = onQuery
    this.#provider = provider
  }

  /**
   * Starts an internal transaction. The difference to `startTransaction` is that it does not
   * use the default transaction options from the `TransactionManager`, which in practice means
   * that it does not apply the default timeouts.
   */
  async startInternalTransaction(options?: Options): Promise<TransactionInfo> {
    const validatedOptions = options !== undefined ? this.#validateOptions(options) : {}
    return await this.tracingHelper.runInChildSpan('start_transaction', () =>
      this.#startTransactionImpl(validatedOptions),
    )
  }

  async startTransaction(options?: Options): Promise<TransactionInfo> {
    const validatedOptions = options !== undefined ? this.#validateOptions(options) : this.transactionOptions
    return await this.tracingHelper.runInChildSpan('start_transaction', () =>
      this.#startTransactionImpl(validatedOptions),
    )
  }

  async #startTransactionImpl(options: Options): Promise<TransactionInfo> {
    if (options.newTxId) {
      return await this.#withActiveTransactionLock(options.newTxId, 'start', async (existing) => {
        if (existing.status !== 'running') {
          throw new TransactionInternalConsistencyError(
            `Transaction in invalid state ${existing.status} when starting a nested transaction.`,
          )
        }
        if (!existing.transaction) {
          throw new TransactionInternalConsistencyError(
            `Transaction missing underlying driver transaction when starting a nested transaction.`,
          )
        }

        existing.depth += 1

        const savepointName = this.#nextSavepointName(existing)
        existing.savepoints.push(savepointName)
        try {
          await this.#requiredCreateSavepoint(existing.transaction)(savepointName)
        } catch (e) {
          // Keep state consistent if creating the savepoint fails.
          existing.depth -= 1
          existing.savepoints.pop()
          throw e
        }

        return { id: existing.id }
      })
    }

    const transaction: TransactionWrapper = {
      id: await randomUUID(),
      status: 'waiting',
      timer: undefined,
      timeout: options.timeout,
      startedAt: Date.now(),
      transaction: undefined,
      operationQueue: Promise.resolve(),
      depth: 1,
      savepoints: [],
      savepointCounter: 0,
    }

    // Start timeout to wait for transaction to be started.
    const abortController = new AbortController()
    const startTimer = createTimeoutIfDefined(() => abortController.abort(), options.maxWait)
    startTimer?.unref?.()

    // Keep a reference to the startTransaction promise so we can clean up
    // if the timeout fires before it completes.
    const startTransactionPromise = this.driverAdapter
      .startTransaction(options.isolationLevel)
      .catch(rethrowAsUserFacing)

    transaction.transaction = await Promise.race([
      startTransactionPromise.finally(() => clearTimeout(startTimer)),
      once(abortController.signal, 'abort').then(() => undefined),
    ])

    this.transactions.set(transaction.id, transaction)

    // Transaction status might have timed out while waiting for transaction to start. => Check for it!
    switch (transaction.status) {
      case 'waiting':
        if (abortController.signal.aborted) {
          // The startTransaction promise may still be running in the background.
          // If it eventually succeeds, we need to roll back and release the connection to
          // avoid leaking it and exhausting the connection pool. For adapters that don't use
          // phantom queries (e.g. pg/neon), `rollback()` only releases the connection without
          // sending SQL, so we send an explicit ROLLBACK first; otherwise the connection returns
          // to the pool mid-transaction because `BEGIN` already ran on the wire during startup.
          // We ignore any errors here because we will have already returned our own
          // `TransactionStartTimeoutError` error to the user.
          void startTransactionPromise
            .then(async (tx) => {
              if (tx.options.usePhantomQuery) {
                await tx.rollback()
              } else {
                try {
                  await tx.executeRaw(ROLLBACK_QUERY())
                } finally {
                  await tx.rollback()
                }
              }
            })
            .catch((e) => debug('error in discarded transaction:', e))

          // Call `#closeTransaction` to update internal state. It won't actually attempt
          // to rollback the tx itself because `transaction.transaction` is undefined.
          await this.#closeTransaction(transaction, 'timed_out')

          throw new TransactionStartTimeoutError()
        }

        transaction.status = 'running'
        // Start timeout to wait for transaction to be finished.
        transaction.timer = this.#startTransactionTimeout(transaction.id, options.timeout)
        return { id: transaction.id }
      case 'timed_out':
      case 'running':
      case 'committed':
      case 'rolled_back':
        throw new TransactionInternalConsistencyError(
          `Transaction in invalid state ${transaction.status} although it just finished startup.`,
        )
      default:
        assertNever(transaction['status'], 'Unknown transaction status.')
    }
  }

  async commitTransaction(transactionId: string): Promise<void> {
    return await this.tracingHelper.runInChildSpan('commit_transaction', async () => {
      await this.#withActiveTransactionLock(transactionId, 'commit', async (txw) => {
        if (txw.depth > 1) {
          if (!txw.transaction) throw new TransactionNotFoundError()
          const savepointName = txw.savepoints.at(-1)
          if (!savepointName) {
            throw new TransactionInternalConsistencyError(
              `Missing savepoint for nested commit. Depth: ${txw.depth}, transactionId: ${txw.id}`,
            )
          }
          try {
            await this.#releaseSavepoint(txw.transaction, savepointName)
          } finally {
            // Keep internal state consistent even if releasing the savepoint fails.
            txw.savepoints.pop()
            txw.depth -= 1
          }
          return
        }
        await this.#closeTransaction(txw, 'committed')
      })
    })
  }

  async rollbackTransaction(transactionId: string): Promise<void> {
    return await this.tracingHelper.runInChildSpan('rollback_transaction', async () => {
      await this.#withActiveTransactionLock(transactionId, 'rollback', async (txw) => {
        if (txw.depth > 1) {
          if (!txw.transaction) throw new TransactionNotFoundError()
          const savepointName = txw.savepoints.at(-1)
          if (!savepointName) {
            throw new TransactionInternalConsistencyError(
              `Missing savepoint for nested rollback. Depth: ${txw.depth}, transactionId: ${txw.id}`,
            )
          }

          try {
            await this.#requiredRollbackToSavepoint(txw.transaction)(savepointName)
            await this.#releaseSavepoint(txw.transaction, savepointName)
          } finally {
            // Keep internal state consistent even if rollback/release fails.
            txw.savepoints.pop()
            txw.depth -= 1
          }
          return
        }
        await this.#closeTransaction(txw, 'rolled_back')
      })
    })
  }

  async getTransaction(txInfo: TransactionInfo, operation: string): Promise<Transaction> {
    let tx = this.#getActiveOrClosingTransaction(txInfo.id, operation)
    if (tx.status === 'closing') {
      await tx.closing
      // Fetch again to ensure proper error propagation after it's been closed.
      tx = this.#getActiveOrClosingTransaction(txInfo.id, operation)
    }
    if (!tx.transaction) throw new TransactionNotFoundError()
    return tx.transaction
  }

  #getActiveOrClosingTransaction(transactionId: string, operation: string): TransactionWrapper {
    const transaction = this.transactions.get(transactionId)

    if (!transaction) {
      const closedTransaction = this.closedTransactions.find((tx) => tx.id === transactionId)
      if (closedTransaction) {
        debug('Transaction already closed.', { transactionId, status: closedTransaction.status })
        switch (closedTransaction.status) {
          case 'closing':
          case 'waiting':
          case 'running':
            throw new TransactionInternalConsistencyError('Active transaction found in closed transactions list.')
          case 'committed':
            throw new TransactionClosedError(operation)
          case 'rolled_back':
            throw new TransactionRolledBackError(operation)
          case 'timed_out':
            throw new TransactionExecutionTimeoutError(operation, {
              timeout: closedTransaction.timeout!,
              timeTaken: Date.now() - closedTransaction.startedAt,
            })
        }
      } else {
        debug(`Transaction not found.`, transactionId)
        throw new TransactionNotFoundError()
      }
    }

    if (['committed', 'rolled_back', 'timed_out'].includes(transaction.status)) {
      throw new TransactionInternalConsistencyError('Closed transaction found in active transactions map.')
    }

    return transaction
  }

  async cancelAllTransactions(): Promise<void> {
    // TODO: call `map` on the iterator directly without collecting it into an array first
    // once we drop support for Node.js 18 and 20.
    await Promise.allSettled(
      [...this.transactions.values()].map((tx) =>
        this.#runSerialized(tx, async () => {
          const current = this.transactions.get(tx.id)
          if (current) {
            await this.#closeTransaction(current, 'rolled_back')
          }
        }),
      ),
    )
  }

  #nextSavepointName(transaction: TransactionWrapper): string {
    return `prisma_sp_${transaction.savepointCounter++}`
  }

  #requiredCreateSavepoint(transaction: Transaction): (name: string) => Promise<void> {
    if (transaction.createSavepoint) {
      return transaction.createSavepoint.bind(transaction)
    }

    throw new TransactionManagerError(
      `Nested transactions are not supported by adapter "${transaction.adapterName}" (${transaction.provider}): createSavepoint is not implemented.`,
    )
  }

  #requiredRollbackToSavepoint(transaction: Transaction): (name: string) => Promise<void> {
    if (transaction.rollbackToSavepoint) {
      return transaction.rollbackToSavepoint.bind(transaction)
    }

    throw new TransactionManagerError(
      `Nested transactions are not supported by adapter "${transaction.adapterName}" (${transaction.provider}): rollbackToSavepoint is not implemented.`,
    )
  }

  async #releaseSavepoint(transaction: Transaction, name: string): Promise<void> {
    if (transaction.releaseSavepoint) {
      await transaction.releaseSavepoint(name)
    }
  }

  #debugTransactionAlreadyClosedOnTimeout(transactionId: string): void {
    // Transaction was already committed or rolled back when timeout happened.
    // Should normally not happen as timeout is cancelled when transaction is committed or rolled back.
    // No further action needed though.
    debug('Transaction already committed or rolled back when timeout happened.', transactionId)
  }

  #startTransactionTimeout(transactionId: string, timeout: number | undefined): NodeJS.Timeout | undefined {
    const timeoutStartedAt = Date.now()
    const timer = createTimeoutIfDefined(async () => {
      debug('Transaction timed out.', { transactionId, timeoutStartedAt, timeout })

      const tx = this.transactions.get(transactionId)
      if (!tx) {
        this.#debugTransactionAlreadyClosedOnTimeout(transactionId)
        return
      }

      await this.#runSerialized(tx, async () => {
        const current = this.transactions.get(transactionId)
        if (current && ['running', 'waiting'].includes(current.status)) {
          await this.#closeTransaction(current, 'timed_out')
        } else {
          this.#debugTransactionAlreadyClosedOnTimeout(transactionId)
        }
      })
    }, timeout)

    timer?.unref?.()
    return timer
  }

  // Any operation that mutates or closes a transaction must run through this lock so
  // status/savepoint/depth checks and updates happen against a stable view of state.
  async #withActiveTransactionLock<T>(
    transactionId: string,
    operation: string,
    callback: (tx: TransactionWrapper) => Promise<T>,
  ): Promise<T> {
    const tx = this.#getActiveOrClosingTransaction(transactionId, operation)
    return await this.#runSerialized(tx, async () => {
      const current = this.#getActiveOrClosingTransaction(transactionId, operation)
      return await callback(current)
    })
  }

  // Serializes operations per transaction id to prevent interleaving across awaits.
  // This avoids races where one operation mutates savepoint/depth state while another
  // operation is suspended, which could otherwise corrupt cleanup logic.
  async #runSerialized<T>(tx: TransactionWrapper, callback: () => Promise<T>): Promise<T> {
    const previousOperation = tx.operationQueue
    let releaseOperationLock!: () => void
    tx.operationQueue = new Promise<void>((resolve) => {
      releaseOperationLock = resolve
    })

    await previousOperation
    try {
      return await callback()
    } finally {
      releaseOperationLock()
    }
  }

  async #closeTransaction(tx: TransactionWrapper, status: 'committed' | 'rolled_back' | 'timed_out'): Promise<void> {
    const createClosingPromise = async () => {
      debug('Closing transaction.', { transactionId: tx.id, status })
      try {
        if (tx.transaction && status === 'committed') {
          if (tx.transaction.options.usePhantomQuery) {
            await this.#withQuerySpanAndEvent(PHANTOM_COMMIT_QUERY(), tx.transaction, () => tx.transaction!.commit())
          } else {
            const query = COMMIT_QUERY()
            await this.#withQuerySpanAndEvent(query, tx.transaction, () => tx.transaction!.executeRaw(query)).then(
              () => tx.transaction!.commit(),
              (err) => {
                const fail = () => Promise.reject(err)
                return tx.transaction!.rollback().then(fail, fail)
              },
            )
          }
        } else if (tx.transaction) {
          if (tx.transaction.options.usePhantomQuery) {
            await this.#withQuerySpanAndEvent(PHANTOM_ROLLBACK_QUERY(), tx.transaction, () =>
              tx.transaction!.rollback(),
            )
          } else {
            const query = ROLLBACK_QUERY()
            try {
              await this.#withQuerySpanAndEvent(query, tx.transaction, () => tx.transaction!.executeRaw(query))
            } finally {
              await tx.transaction.rollback()
            }
          }
        }
      } finally {
        tx.status = status
        clearTimeout(tx.timer)
        tx.timer = undefined

        this.transactions.delete(tx.id)

        this.closedTransactions.push(tx)
        if (this.closedTransactions.length > MAX_CLOSED_TRANSACTIONS) {
          this.closedTransactions.shift()
        }
      }
    }

    if (tx.status === 'closing') {
      await tx.closing
      // Fetch again to ensure proper error propagation after it's been closed.
      this.#getActiveOrClosingTransaction(tx.id, status === 'committed' ? 'commit' : 'rollback')
    } else {
      await Object.assign(tx, {
        status: 'closing',
        reason: status,
        closing: createClosingPromise(),
      }).closing
    }
  }

  #validateOptions(options: Options) {
    // Supplying timeout default values is cared for upstream already.
    if (!options.timeout) throw new TransactionManagerError('timeout is required')
    if (!options.maxWait) throw new TransactionManagerError('maxWait is required')

    // Snapshot level only supported for MS SQL Server, which is not supported via driver adapters so far.
    if (options.isolationLevel === 'SNAPSHOT') throw new InvalidTransactionIsolationLevelError(options.isolationLevel)

    return {
      ...options,
      timeout: options.timeout,
      maxWait: options.maxWait,
    }
  }

  #withQuerySpanAndEvent<T>(query: SqlQuery, queryable: SqlQueryable, execute: () => Promise<T>): Promise<T> {
    return withQuerySpanAndEvent({
      query,
      execute,
      provider: this.#provider ?? queryable.provider,
      tracingHelper: this.tracingHelper,
      onQuery: this.#onQuery,
    })
  }
}

function createTimeoutIfDefined(cb: () => void, ms: number | undefined): NodeJS.Timeout | undefined {
  return ms !== undefined ? setTimeout(cb, ms) : undefined
}
