// a socket lives as long as it stays connected, but the token that opened it
// does not. dropping it at expiry keeps a socket from outliving a session every
// HTTP route would already have rejected
function disconnectAtExpiry(socket: NoteSocket): void {
  const remaining = socket.data.expiresAt - Date.now();

  if (remaining <= 0) {
    socket.disconnect(true);
    return;
  }

  // an expiry further off than one timer reaches is waited for in steps rather
  // than left unwatched
  const timer = setTimeout(
    () => (remaining > maxDelay ? disconnectAtExpiry(socket) : socket.disconnect(true)),
    Math.min(remaining, maxDelay),
  );

  timer.unref();
  socket.once('disconnect', () => clearTimeout(timer));
}

/** Puts the socket in a note's room, if the account may read that note. */
async function join(socket: NoteSocket, payload: unknown, ack?: (result: JoinResult) => void) {
  const noteId = readNoteId(payload);

  if (noteId === null) {
    ack?.({ ok: false, error: 'A note id is required' });
    return;
  }

  // checked on every join rather than once at connect - a room joined an hour
  // ago is no evidence that the share behind it still stands
  if (!(await canReadNote(socket.data.userId, noteId))) {
    logger.warn({ userId: socket.data.userId, noteId }, 'Socket refused a note it may not read');
    ack?.({ ok: false, error: notFound });
    return;
  }

  await socket.join(noteRoom(noteId));

  // the share can be taken back between the check above and the join itself,
  // and the revoke that empties the room would have found nobody in it. asking
  // again once the socket is in closes that gap from both ends
  if (!(await canReadNote(socket.data.userId, noteId))) {
    await socket.leave(noteRoom(noteId));
    ack?.({ ok: false, error: notFound });
    return;
  }

  ack?.({ ok: true });
}

// socket ids and room names share one namespace, so a header naming the note's
// own room would otherwise exclude everybody in it. only a socket that belongs
// to whoever saved the note may be left out
function excludable(savedBy: number, socketId: string | undefined): string | undefined {
  if (io === null || socketId === undefined) {
    return undefined;
  }

  return io.sockets.sockets.get(socketId)?.data.userId === savedBy ? socketId : undefined;
}

/** Tells everybody in a note's room that it changed, except whoever saved it. */
export function noteUpdated(note: Note, savedBy: number, exceptSocketId?: string): void {
  if (io === null) {
    return;
  }

  const change: NoteChange = {
    id: note.id,
    title: note.title,
    content: note.content,
    updatedAt: note.updatedAt.toISOString(),
  };

  const room = io.to(noteRoom(note.id));

  // the editor that saved this already has it, and an echo would land on top of
  // whatever has been typed since the save went out
  const quiet = excludable(savedBy, exceptSocketId);
  const audience = quiet === undefined ? room : room.except(quiet);

  audience.emit('note:updated', change);
}

/** Tells everybody in a note's room that it is gone, and empties the room. */
export function noteDeleted(id: number): void {
  if (io === null) {
    return;
  }

  io.to(noteRoom(id)).emit('note:deleted', { id });
  io.in(noteRoom(id)).socketsLeave(noteRoom(id));
}

/** Tells an account that a note has been shared with it. */
export function shareGranted(userId: number, noteId: number): void {
  if (io === null) {
    return;
  }

  // the note itself is not sent - the recipient asks for it, and gets it shaped
  // with the permission they were just given
  io.to(userRoom(userId)).emit('share:granted', { noteId });
}

/**
 * Tells an account a note is no longer shared with it, and takes the room away.
 *
 * Leaving the room is the point. A socket that joined while the share stood
 * would otherwise keep receiving that note's content after it was taken back,
 * which is a permission leak rather than a stale screen.
 */
export function shareRevoked(userId: number, noteId: number): void {
  if (io === null) {
    return;
  }

  io.to(userRoom(userId)).emit('share:revoked', { noteId });
  io.in(userRoom(userId)).socketsLeave(noteRoom(noteId));
}

/**
 * Drops the sockets an account already has open.
 *
 * The handshake checks the token version, but only once. A socket that was
 * authenticated before a password change would otherwise keep working on the
 * withdrawn session until its token expired.
 */
export function sessionsWithdrawn(userId: number): void {
  if (io === null) {
    return;
  }

  io.in(userRoom(userId)).disconnectSockets(true);
}

/** Starts the socket server on the same http server the API is served from. */
export function attachRealtime(server: HttpServer): NoteServer {
  const created: NoteServer = new Server(server, { path: realtimePath });

  // the same parser app.ts mounts, so the session cookie is read one way only
  created.engine.use(cookieParser());
  created.use((socket, next) => {
    authenticate(socket, next).catch((cause: unknown) => {
      logger.error({ err: cause }, 'Socket authentication failed');
      next(new Error('Authentication required'));
    });
  });

  created.on('connection', (socket) => {
    socket.join(userRoom(socket.data.userId));
    disconnectAtExpiry(socket);

    socket.on('note:join', (payload, ack) => {
      // nothing else would catch this, and a client left without an answer
      // would wait for one forever
      join(socket, payload, ack).catch((cause: unknown) => {
        logger.error({ err: cause, userId: socket.data.userId }, 'Socket join failed');
        ack?.({ ok: false, error: 'Could not join that note' });
      });
    });
    socket.on('note:leave', (payload) => {
      const noteId = readNoteId(payload);

      if (noteId !== null) void socket.leave(noteRoom(noteId));
    });
  });

  io = created;

  return created;
}

/**
 * Stops the socket server and disconnects everybody.
 *
 * Closing it closes the http server it was attached to as well, which is what
 * the tests rely on to stop mocha hanging on an open handle.
 */
export function closeRealtime(): Promise<void> {
  const closing = io;

  io = null;

  return closing === null
    ? Promise.resolve()
    : new Promise((resolve) => closing.close(() => resolve()));
}

import { z } from 'zod';

import { prisma } from '../db/prisma.js';
import type { Prisma } from '../generated/prisma/client.js';
import { htmlToText } from '../utils/html.js';
import { HttpError } from '../utils/httpError.js';
import { logger } from '../utils/logger.js';
import { sanitiseHtml } from '../utils/sanitiseHtml.js';
import { parseOrThrow } from '../utils/validation.js';
import { findUserByEmail, userSummaryFields, type UserSummary } from './authService.js';

/** What a share grants the account it was given to. */
export type SharePermission = 'view' | 'edit';

/** What the account asking may do with a note. Owning it outranks any share. */
export type NotePermission = 'owner' | SharePermission;

/** A note as the client sees it. */
export interface Note {
  id: number;
  title: string;
  content: string;
  pinned: boolean;
  createdAt: Date;
  updatedAt: Date;
  owner: UserSummary;
  permission: NotePermission;
}

/** A list of notes, and how many the filter matched in total. */
export interface NoteList {
  notes: Note[];
  total: number;
}

/** A share of one note with one account, as the owner sees it listed. */
export interface Share {
  user: UserSummary;
  permission: SharePermission;
  createdAt: Date;
}

/** A note as it appears in an export file. */
export interface ExportedNote {
  title: string;
  content: string;
  pinned: boolean;
  createdAt: Date;
  updatedAt: Date;
}

/** How many notes are read from the database at a time when exporting. */
export const exportBatch = 100;

/** The version this server writes, and the only one it reads back. */
export const exportVersion = 1;

/** The most notes one import may carry. */
export const importLimit = 200;

/** The most notes one page of a list may hold. */
export const pageLimit = 100;

/** The page size used when a page was asked for without saying how big. */
export const defaultPageSize = 20;

/**
 * The most content one note may hold, in bytes. The column takes 16MB, but
 * nothing anyone types is near this, and the cap makes an oversized note a 400
 * rather than a failed insert.
 */
export const contentLimit = 1_000_000;

// the title column is varchar(191) and mysql errors rather than truncating
const title = z
  .string()
  .trim()
  .min(1, 'Title is required')
  .max(191, 'Title must be 191 characters or fewer');

// the size is checked before sanitising rather than after: an oversized body is
// turned away without doing the work, and sanitising only ever makes it smaller
const content = z
  .string()
  .refine((value) => Buffer.byteLength(value) <= contentLimit, 'Content is too long')
  .transform(sanitiseHtml);

/** What createNote accepts. The routes validate against this too. */
export const createNoteSchema = z.object({
  title,
  content: content.default(''),
});

/** What updateNote accepts. At least one field has to be present. */
export const updateNoteSchema = z
  .object({
    title: title.optional(),
    content: content.optional(),
    pinned: z.boolean().optional(),
  })
  .refine(
    (body) => body.title !== undefined || body.content !== undefined || body.pinned !== undefined,
    'Give a title, content or pinned to change',
  );

/** What sharing a note accepts. The route validates against this too. */
export const shareNoteSchema = z.object({
  email: z.email('Enter a valid email address'),
  permission: z.enum(['view', 'edit']).default('view'),
});

/** What the list route accepts as a query string. */
export const listNotesSchema = z.object({
  // a cleared search box sends q=, which means no search rather than no results
  q: z
    .string()
    .trim()
    .max(191, 'Search is too long')
    .optional()
    .transform((value) => (value === '' ? undefined : value)),
  sort: z.enum(['recent', 'oldest', 'title', 'created']).default('recent'),
  // paging is off unless one of these is asked for, so a client that knows
  // nothing about it still gets everything it did before
  page: z.preprocess(
    (value) => (value === '' ? undefined : value),
    z.coerce
      .number()
      .int('Page must be a whole number')
      .min(1, 'Page must be at least 1')
      .optional(),
  ),
  limit: z.preprocess(
    (value) => (value === '' ? undefined : value),
    z.coerce
      .number()
      .int('Limit must be a whole number')
      .min(1, 'Limit must be at least 1')
      .max(pageLimit, `Limit can be at most ${pageLimit}`)
      .optional(),
  ),
});

/** What an import file has to look like. */
export const importSchema = z.object({
  version: z.literal(exportVersion, 'Unsupported export version'),
  notes: z
    .array(
      z.object({
        title,
        content: content.default(''),
        // absent in a file written before pinning existed, which still imports
        pinned: z.boolean().default(false),
        createdAt: z.coerce.date().optional(),
        updatedAt: z.coerce.date().optional(),
      }),
    )
    .max(importLimit, `An import can hold at most ${importLimit} notes`),
});

export type CreateNoteInput = z.infer<typeof createNoteSchema>;
export type UpdateNoteInput = z.infer<typeof updateNoteSchema>;
export type ShareNoteInput = z.infer<typeof shareNoteSchema>;

// the reader's own share is selected alongside the note so the permission comes
// back with it rather than costing a second query per note
function noteFields(userId: number) {
  return {
    id: true,
    title: true,
    content: true,
    pinned: true,
    createdAt: true,
    updatedAt: true,
    authorId: true,
    author: { select: userSummaryFields },
    shares: { where: { userId }, select: { permission: true } },
  } as const;
}

interface NoteRow {
  id: number;
  title: string;
  content: string;
  pinned: boolean;
  createdAt: Date;
  updatedAt: Date;
  authorId: number;
  author: UserSummary;
  shares: { permission: SharePermission }[];
}

/** A stored row as the client sees it, carrying what this reader may do to it. */
function toNote(row: NoteRow, userId: number): Note {
  return {
    id: row.id,
    title: row.title,
    content: row.content,
    pinned: row.pinned,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    owner: row.author,
    permission: row.authorId === userId ? 'owner' : (row.shares[0]?.permission ?? 'view'),
  };
}

// what a user may read: their own notes, plus anything shared with them
function readable(userId: number) {
  return { OR: [{ authorId: userId }, { shares: { some: { userId } } }] };
}

// the same, narrowed to the shares that granted editing
function writable(userId: number) {
  return {
    OR: [{ authorId: userId }, { shares: { some: { userId, permission: 'edit' as const } } }],
  };
}

const exportFields = {
  title: true,
  content: true,
  pinned: true,
  createdAt: true,
  updatedAt: true,
} as const;

const ordering = {
  recent: { updatedAt: 'desc' },
  oldest: { updatedAt: 'asc' },
  title: { title: 'asc' },
  created: { createdAt: 'desc' },
} as const;

const notFound = 'Note not found';

// prisma puts the term straight into a LIKE, so % and _ would otherwise be
// wildcards and a search for "%" would return everything
function searchTerm(q: string): string {
  return q.replace(/[\\%_]/g, (char) => `\\${char}`);
}

// the two lists differ only by which notes they draw from - the searching, the
// ordering and the shape they come back in are the same job
async function listBy(
  userId: number,
  where: Prisma.NoteWhereInput,
  query: unknown,
): Promise<NoteList> {
  const { q, sort, page, limit } = parseOrThrow(listNotesSchema, query);
  const term = q === undefined ? undefined : searchTerm(q);

  const filter: Prisma.NoteWhereInput = {
    ...where,
    // title or body, because someone searching for a word does not know which it is in
    ...(term === undefined
      ? {}
      : {
          OR: [{ title: { contains: term } }, { contentText: { contains: term } }],
        }),
  };

  const size = limit ?? defaultPageSize;
  const paged = page !== undefined || limit !== undefined;

  const [rows, total] = await Promise.all([
    prisma.note.findMany({
      where: filter,
      // pinned first whatever the sort is, which is the point of pinning
      orderBy: [{ pinned: 'desc' }, ordering[sort]],
      select: noteFields(userId),
      ...(paged ? { skip: ((page ?? 1) - 1) * size, take: size } : {}),
    }),
    // the whole count, not the page's, so a client can say how far it has got
    prisma.note.count({ where: filter }),
  ]);

  return { notes: rows.map((row) => toNote(row, userId)), total };
}

/** Lists a user's own notes, filtered by the search term and in the order asked for. */
export function listNotes(userId: number, query: unknown = {}): Promise<NoteList> {
  return listBy(userId, { authorId: userId }, query);
}

/** Lists the notes other accounts have shared with this one. */
export function listSharedNotes(userId: number, query: unknown = {}): Promise<NoteList> {
  return listBy(userId, { shares: { some: { userId } } }, query);
}

/** Returns a note the user owns or has been shared, or throws 404. */
export async function getNote(userId: number, id: number): Promise<Note> {
  const note = await prisma.note.findFirst({
    where: { id, ...readable(userId) },
    select: noteFields(userId),
  });

  if (note === null) {
    throw new HttpError(404, notFound);
  }

  return toNote(note, userId);
}

/** Whether the user may read a note, for a caller that wants no note back. */
export async function canReadNote(userId: number, id: number): Promise<boolean> {
  const note = await prisma.note.findFirst({
    where: { id, ...readable(userId) },
    select: { id: true },
  });

  return note !== null;
}

/** Creates a note owned by the user. */
export async function createNote(authorId: number, input: CreateNoteInput): Promise<Note> {
  const data = parseOrThrow(createNoteSchema, input);

  const note = await prisma.note.create({
    data: { ...data, contentText: htmlToText(data.content), authorId },
    select: noteFields(authorId),
  });

  logger.info({ userId: authorId, noteId: note.id }, 'Note created');

  return toNote(note, authorId);
}

/** Changes the given fields of a note the user may write, or throws 404. */
export async function updateNote(
  userId: number,
  id: number,
  input: UpdateNoteInput,
): Promise<Note> {
  const data = parseOrThrow(updateNoteSchema, input);

  // pinning is the owner's own ordering of their list, not something an edit
  // share hands over, so changing it needs more than being able to write
  const allowed = data.pinned === undefined ? writable(userId) : { authorId: userId };

  // the permission is part of the write rather than a read then a write, so a
  // share cannot be revoked in the gap between checking it and using it
  const { count } = await prisma.note.updateMany({
    where: { id, ...allowed },
    data: {
      ...data,
      ...(data.content === undefined ? {} : { contentText: htmlToText(data.content) }),
    },
  });

  if (count === 0) {
    throw new HttpError(404, notFound);
  }

  logger.info({ userId, noteId: id }, 'Note updated');

  return getNote(userId, id);
}

/**
 * Deletes a note, or throws 404.
 *
 * Owner only. Editing somebody's note is not the same right as destroying it, so
 * this keeps the plain authorId check the other writes have outgrown.
 */
export async function deleteNote(userId: number, id: number): Promise<void> {
  const { count } = await prisma.note.deleteMany({ where: { id, authorId: userId } });

  if (count === 0) {
    throw new HttpError(404, notFound);
  }

  logger.info({ userId, noteId: id }, 'Note deleted');
}

const shareFields = {
  user: { select: userSummaryFields },
  permission: true,
  createdAt: true,
} as const;

const shareNotFound = 'Share not found';

/** Throws 404 unless the note exists and this user owns it. */
async function ownedOrThrow(userId: number, id: number): Promise<void> {
  const note = await prisma.note.findFirst({
    where: { id, authorId: userId },
    select: { id: true },
  });

  if (note === null) {
    throw new HttpError(404, notFound);
  }
}

/** Who a note the user owns has been shared with. */
export async function listShares(userId: number, id: number): Promise<Share[]> {
  await ownedOrThrow(userId, id);

  return prisma.noteShare.findMany({
    where: { noteId: id },
    orderBy: { createdAt: 'asc' },
    select: shareFields,
  });
}

/**
 * Shares a note with another account, or changes what an existing share grants.
 *
 * `created` is false when the share was already there, which is the difference
 * between answering 201 and 200. The lookup that decides it is only for that -
 * the upsert below is what makes two people sharing at once safe.
 */
export async function shareNote(
  userId: number,
  id: number,
  input: ShareNoteInput,
): Promise<{ share: Share; created: boolean }> {
  const { email, permission } = parseOrThrow(shareNoteSchema, input);

  await ownedOrThrow(userId, id);

  const recipient = await findUserByEmail(email);

  if (recipient === null) {
    // deliberately the same wording whichever of the two was wrong. it does not
    // close the hole - the share list still shows who was added - but it stops
    // the route being a plain yes/no oracle for whether an address has an
    // account. the rate limit on it is what does the real work
    logger.warn({ userId, noteId: id }, 'Share attempted for an unknown address');
    throw new HttpError(404, 'That note could not be shared with that address');
  }

  if (recipient.id === userId) {
    throw new HttpError(400, 'You already own this note');
  }

  const key = { noteId_userId: { noteId: id, userId: recipient.id } };
  const existing = await prisma.noteShare.findUnique({ where: key, select: { id: true } });

  const share = await prisma.noteShare.upsert({
    where: key,
    create: { noteId: id, userId: recipient.id, permission },
    update: { permission },
    select: shareFields,
  });

  logger.info({ userId, noteId: id, targetUserId: recipient.id, permission }, 'Note shared');

  return { share, created: existing === null };
}

/** Removes a share. The owner may take it back, and the reader may drop it. */
export async function unshareNote(userId: number, id: number, targetUserId: number): Promise<void> {
  // giving a note back does not need the owner's permission
  if (targetUserId !== userId) {
    await ownedOrThrow(userId, id);
  }

  const { count } = await prisma.noteShare.deleteMany({
    where: { noteId: id, userId: targetUserId },
  });

  if (count === 0) {
    throw new HttpError(404, shareNotFound);
  }

  logger.info({ userId, noteId: id, targetUserId }, 'Share removed');
}

/**
 * Everything the user has written, in the shape importNotes reads back.
 *
 * Read a page at a time and handed over one note at a time, so an account with a
 * lot of large notes never has all of them in memory at once. The pages walk by
 * id because it is unique and stable, which a timestamp is not.
 */
export async function* eachNoteToExport(authorId: number): AsyncGenerator<ExportedNote> {
  let after: number | undefined;

  for (;;) {
    const page = await prisma.note.findMany({
      where: { authorId },
      orderBy: { id: 'asc' },
      take: exportBatch,
      ...(after === undefined ? {} : { cursor: { id: after }, skip: 1 }),
      select: { id: true, ...exportFields },
    });

    const last = page.at(-1);

    if (last === undefined) {
      return;
    }

    for (const note of page) {
      yield {
        title: note.title,
        content: note.content,
        pinned: note.pinned,
        createdAt: note.createdAt,
        updatedAt: note.updatedAt,
      };
    }

    if (page.length < exportBatch) {
      return;
    }

    after = last.id;
  }
}

/** Adds the notes from an export file to the user's own, and says how many. */
export async function importNotes(authorId: number, input: unknown): Promise<number> {
  const { notes } = parseOrThrow(importSchema, input);

  const { count } = await prisma.note.createMany({
    data: notes.map((note) => ({
      title: note.title,
      content: note.content,
      contentText: htmlToText(note.content),
      pinned: note.pinned,
      authorId,
      // keeping the original dates makes a restore look like the notes never left
      ...(note.createdAt === undefined ? {} : { createdAt: note.createdAt }),
      ...(note.updatedAt === undefined ? {} : { updatedAt: note.updatedAt }),
    })),
  });

  logger.info({ userId: authorId, count }, 'Notes imported');

  return count;
}

const named: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
};

/** Decodes one entity, or leaves it alone if it is not one we know. */
function decode(entity: string, code: string): string {
  if (code.startsWith('#')) {
    const point = code.startsWith('#x')
      ? Number.parseInt(code.slice(2), 16)
      : Number.parseInt(code.slice(1), 10);

    // fromCodePoint throws on anything outside the unicode range
    if (Number.isInteger(point) && point >= 0 && point <= 0x10ffff) {
      return String.fromCodePoint(point);
    }

    return entity;
  }

  return named[code.toLowerCase()] ?? entity;
}

/**
 * The readable text of stored note HTML, for searching.
 *
 * Notes are saved as HTML, so searching the markup itself matches tag names -
 * "strong" would find every bolded note. This is what the note says instead.
 */
export function htmlToText(html: string): string {
  return html
    .replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, decode)
    .replace(/\s+/g, ' ')
    .trim();
}

import sanitizeHtml from 'sanitize-html';

// the blocks the editor can align. a style attribute is allowed nowhere else
const alignable = ['p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6'];

// exactly what the editor's extensions can produce. anything else arrived from
// somewhere other than the editor, and a note is read in other people's
// browsers once it is shared
const options: sanitizeHtml.IOptions = {
  allowedTags: [
    'p',
    'br',
    'hr',
    'h1',
    'h2',
    'h3',
    'h4',
    'h5',
    'h6',
    'strong',
    'em',
    's',
    'u',
    'code',
    'pre',
    'blockquote',
    'ul',
    'ol',
    'li',
    'a',
  ],
  allowedAttributes: {
    a: ['href', 'target', 'rel', 'title'],
    // written when an ordered list does not start at 1, or is not numbered
    ol: ['start', 'type'],
    // the editor writes alignment as an inline style, so these blocks are the
    // only ones allowed to carry one at all
    ...Object.fromEntries(alignable.map((tag) => [tag, ['style']])),
  },
  /**
   * The one property an inline style may set, and the only four values it may
   * hold. Everything else in a style attribute is dropped, so a smuggled
   * position:fixed or background:url(...) does not survive alongside a real
   * alignment.
   */
  allowedStyles: {
    '*': { 'text-align': [/^(?:left|right|center|justify)$/] },
  },
  // the only class the editor writes is the code block's language
