import { expect } from 'chai';
import request from 'supertest';

import { createApp } from '../src/app.js';
import { isDatabaseReachable, prisma } from '../src/db/prisma.js';

const app = createApp();

const password = 'correct horse battery';

interface ApiNote {
  id: number;
  title: string;
  pinned: boolean;
  updatedAt: string;
}

async function signIn(email: string): Promise<ReturnType<typeof request.agent>> {
  const agent = request.agent(app);
  await agent.post('/api/auth/register').send({ email, password });

  return agent;
}

async function createNote(
  agent: ReturnType<typeof request.agent>,
  title: string,
): Promise<ApiNote> {
  const response = await agent.post('/api/notes').send({ title, content: '' });

  return response.body.note as ApiNote;
}

/** The id of the account that registered with this address. */
async function userId(email: string): Promise<number> {
  const { id } = await prisma.user.findUniqueOrThrow({ where: { email } });

  return id;
}

after(async () => {
  await prisma.$disconnect();
});

describe('pinning', function () {
  before(async function () {
    if (!(await isDatabaseReachable())) {
      this.skip();
    }
  });

  beforeEach(async () => {
    await prisma.noteShare.deleteMany();
    await prisma.note.deleteMany();
    await prisma.user.deleteMany();
  });

  it('starts a note unpinned', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    expect(note.pinned).to.equal(false);
  });

  it('pins a note', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    const response = await agent.patch(`/api/notes/${note.id}`).send({ pinned: true });

    expect(response.status).to.equal(200);
    expect(response.body.note.pinned).to.equal(true);
  });

  it('unpins it again', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    await agent.patch(`/api/notes/${note.id}`).send({ pinned: true });
    const response = await agent.patch(`/api/notes/${note.id}`).send({ pinned: false });

    expect(response.body.note.pinned).to.equal(false);
  });

  it('puts pinned notes first, whatever the sort', async () => {
    const agent = await signIn('ahtsham@example.com');

    const first = await createNote(agent, 'Aaa oldest');
    await createNote(agent, 'Bbb');
    await createNote(agent, 'Ccc newest');

    await agent.patch(`/api/notes/${first.id}`).send({ pinned: true });

    for (const sort of ['recent', 'oldest', 'title', 'created']) {
      const { body } = await agent.get(`/api/notes?sort=${sort}`);

      expect(body.notes[0].id, `sorted by ${sort}`).to.equal(first.id);
    }
  });

  it('keeps the chosen order among the notes that are not pinned', async () => {
    const agent = await signIn('ahtsham@example.com');

    await createNote(agent, 'Bbb');
    await createNote(agent, 'Aaa');

    const { body } = await agent.get('/api/notes?sort=title');

    expect(body.notes.map((note: { title: string }) => note.title)).to.deep.equal(['Aaa', 'Bbb']);
  });

  it('changes nothing else when it pins', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    const { body } = await agent.patch(`/api/notes/${note.id}`).send({ pinned: true });

    expect(body.note.title).to.equal('A note');
  });

  it('rejects a pinned that is not a boolean', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    const response = await agent.patch(`/api/notes/${note.id}`).send({ pinned: 'yes' });

    expect(response.status).to.equal(400);
  });

  it('still refuses a patch with nothing in it', async () => {
    const agent = await signIn('ahtsham@example.com');
    const note = await createNote(agent, 'A note');

    const response = await agent.patch(`/api/notes/${note.id}`).send({});

    expect(response.status).to.equal(400);
  });

  describe('who may pin', () => {
    it('does not let an edit share pin a note it does not own', async () => {
      const owner = await signIn('owner@example.com');
      const reader = await signIn('reader@example.com');
      const note = await createNote(owner, 'A note');

      await prisma.noteShare.create({
        data: { noteId: note.id, userId: await userId('reader@example.com'), permission: 'edit' },
      });

      // the same share can write the words, so this is the pin being refused
      expect(
        (await reader.patch(`/api/notes/${note.id}`).send({ title: 'Edited' })).status,
      ).to.equal(200);

      const response = await reader.patch(`/api/notes/${note.id}`).send({ pinned: true });

      expect(response.status).to.equal(404);
    });

    it('does not let a stranger pin a note', async () => {
      const owner = await signIn('owner@example.com');
      const stranger = await signIn('stranger@example.com');
      const note = await createNote(owner, 'A note');

      const response = await stranger.patch(`/api/notes/${note.id}`).send({ pinned: true });

      expect(response.status).to.equal(404);
    });
  });

  describe('export and import', () => {
    it('carries the pin through an export', async () => {
      const agent = await signIn('ahtsham@example.com');
      const note = await createNote(agent, 'A note');

      await agent.patch(`/api/notes/${note.id}`).send({ pinned: true });

      const { body } = await agent.get('/api/notes/export');

      expect(body.notes[0].pinned).to.equal(true);
    });

    it('reads the pin back in', async () => {
      const agent = await signIn('ahtsham@example.com');

      await agent
        .post('/api/notes/import')
        .send({ version: 1, notes: [{ title: 'Pinned', content: '', pinned: true }] });

      const { body } = await agent.get('/api/notes');

      expect(body.notes[0].pinned).to.equal(true);
    });

    it('imports a file written before pinning existed', async () => {
      const agent = await signIn('ahtsham@example.com');

      const response = await agent
        .post('/api/notes/import')
        .send({ version: 1, notes: [{ title: 'Old', content: '' }] });

      expect(response.status).to.equal(201);

      const { body } = await agent.get('/api/notes');

      expect(body.notes[0].pinned).to.equal(false);
    });
  });
});

import { createServer, type Server as HttpServer } from 'node:http';
import type { AddressInfo } from 'node:net';

import { expect } from 'chai';
import { io as openSocket, type Socket as ClientSocket } from 'socket.io-client';
import request from 'supertest';

import { createApp } from '../src/app.js';
import { isDatabaseReachable, prisma } from '../src/db/prisma.js';
import {
  attachRealtime,
  closeRealtime,
  realtimePath,
  type JoinResult,
} from '../src/realtime/socket.js';

const password = 'correct horse battery';

let server: HttpServer;
let hub: ReturnType<typeof attachRealtime>;
let url: string;

// closed after every test, so one test's socket cannot answer the next one's
const clients: ClientSocket[] = [];

/** Registers an account and hands back the session cookie it was given. */
async function signIn(email: string): Promise<string> {
  const response = await request(server).post('/api/auth/register').send({ email, password });
  const [cookie] = response.headers['set-cookie'];

  return cookie;
}

/** The id of the account that registered with this address. */
async function userId(email: string): Promise<number> {
  const { id } = await prisma.user.findUniqueOrThrow({ where: { email } });

  return id;
}

/** A note as the API answers with it, once the dates have been through JSON. */
interface ApiNote {
  id: number;
  title: string;
  content: string;
  updatedAt: string;
}

/** Creates a note through the API as whoever the cookie belongs to. */
async function createNote(cookie: string, title: string, content = ''): Promise<ApiNote> {
  const response = await request(server)
    .post('/api/notes')
    .set('Cookie', cookie)
    .send({ title, content });

  return response.body.note as ApiNote;
}

/** Opens a socket, carrying the cookie if it was given one. */
function open(cookie?: string): ClientSocket {
  const socket = openSocket(url, {
    path: realtimePath,
    extraHeaders: cookie === undefined ? {} : { Cookie: cookie },
    // otherwise two accounts in one test would share a single connection
    forceNew: true,
  });

  clients.push(socket);

  return socket;
}

/** Resolves once the socket is connected, rejects with why it could not be. */
function connected(socket: ClientSocket): Promise<ClientSocket> {
  return new Promise((resolve, reject) => {
    socket.once('connect', () => resolve(socket));
    socket.once('connect_error', (cause: Error) => reject(cause));
  });
}

/** Opens a connected socket for whoever the cookie belongs to. */
function socketFor(cookie: string): Promise<ClientSocket> {
  return connected(open(cookie));
}

/** Shares a note with an address, through the route rather than the table. */
function shareWith(cookie: string, noteId: number, email: string, permission = 'view') {
  return request(server)
    .post(`/api/notes/${noteId}/shares`)
    .set('Cookie', cookie)
    .send({ email, permission });
}

/** Takes a share back, through the route. */
function unshare(cookie: string, noteId: number, targetUserId: number) {
  return request(server)
    .delete(`/api/notes/${noteId}/shares/${targetUserId}`)
    .set('Cookie', cookie);
}

/** Saves a change to a note, naming the socket that made it where there is one. */
function saveNote(cookie: string, noteId: number, body: object, socketId?: string) {
  const call = request(server).patch(`/api/notes/${noteId}`).set('Cookie', cookie);

  return (socketId === undefined ? call : call.set('x-socket-id', socketId)).send(body);
}

/** The next event of this name, or a rejection saying it never came. */
function nextEvent<T>(socket: ClientSocket, event: string, within = 2000): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`No ${event} within ${within}ms`)), within);

    socket.once(event, (payload: T) => {
      clearTimeout(timer);
      resolve(payload);
    });
  });
}

/** Whether nothing of this name arrived in the window. Proving a negative costs time. */
function heardNothing(socket: ClientSocket, event: string, within = 400): Promise<boolean> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(true), within);

    socket.once(event, () => {
      clearTimeout(timer);
      resolve(false);
    });
  });
}

/** Asks to join a note and hands back what the server answered. */
async function join(socket: ClientSocket, noteId: unknown): Promise<JoinResult> {
  return (await socket.emitWithAck('note:join', { noteId })) as JoinResult;
}

after(async () => {
  await prisma.$disconnect();
});

describe('realtime', function () {
  before(async function () {
    if (!(await isDatabaseReachable())) {
      this.skip();
    }

    server = createServer(createApp());
    hub = attachRealtime(server);

    await new Promise<void>((resolve) => {
      server.listen(0, resolve);
    });

    url = `http://localhost:${(server.address() as AddressInfo).port}`;
  });

  after(async () => {
    // closing the socket server closes the http server it was attached to, so
    // there is no open handle left for mocha to wait on
    await closeRealtime();
  });

  beforeEach(async () => {
    // shares point at both of the others, so they go first
    await prisma.noteShare.deleteMany();
    await prisma.note.deleteMany();
    await prisma.user.deleteMany();
  });

  afterEach(() => {
    while (clients.length > 0) {
      clients.pop()?.close();
    }
  });

  describe('connecting', () => {
    it('refuses a socket carrying no session cookie', async () => {
      const failure = await connected(open()).catch((cause: Error) => cause);

      expect(failure).to.be.an('error').with.property('message', 'Authentication required');
    });

    it('refuses a socket whose session has been withdrawn', async () => {
      const cookie = await signIn('ahtsham@example.com');

      // the socket would connect on this cookie a moment ago
      await connected(open(cookie));

      await request(server)
        .patch('/api/auth/password')
        .set('Cookie', cookie)
        .send({ currentPassword: password, newPassword: 'a whole new secret' });

      const failure = await connected(open(cookie)).catch((cause: Error) => cause);

      expect(failure).to.be.an('error').with.property('message', 'Authentication required');
    });

    it('drops a socket already open when the password changes', async () => {
      const cookie = await signIn('ahtsham@example.com');
      const socket = await connected(open(cookie));

      // listened for before the change, so the disconnect cannot be missed
      const dropped = nextEvent<string>(socket, 'disconnect');

      await request(server)
        .patch('/api/auth/password')
        .set('Cookie', cookie)
        .send({ currentPassword: password, newPassword: 'a whole new secret' });

      expect(await dropped).to.equal('io server disconnect');
    });

    it('refuses a socket whose token does not verify', async () => {
      const failure = await connected(open('token=not-a-real-token')).catch(
        (cause: Error) => cause,
      );

      expect(failure).to.be.an('error').with.property('message', 'Authentication required');
    });

    it('connects a signed-in socket and puts it in a room of its own', async () => {
      const cookie = await signIn('owner@example.com');

      await socketFor(cookie);

      const room = `user:${await userId('owner@example.com')}`;
      const waiting = await hub.in(room).fetchSockets();

      expect(waiting).to.have.lengthOf(1);
    });
  });

  describe('joining a note', () => {
    it('lets the owner in', async () => {
      const cookie = await signIn('owner@example.com');
      const note = await createNote(cookie, 'Rota');

      expect(await join(await socketFor(cookie), note.id)).to.deep.equal({ ok: true });
    });

    it('lets somebody the note is shared with in', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      expect(await join(await socketFor(reader), note.id)).to.deep.equal({ ok: true });
    });

    it('keeps out an account the note was never shared with', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const stranger = await signIn('stranger@example.com');

      // the same wording the HTTP route uses - a different answer would confirm
      // that the note exists
      expect(await join(await socketFor(stranger), note.id)).to.deep.equal({
        ok: false,
        error: 'Note not found',
      });
    });

    it('refuses a join that names no note', async () => {
      const cookie = await signIn('owner@example.com');

      expect(await join(await socketFor(cookie), 'nine')).to.deep.equal({
        ok: false,
        error: 'A note id is required',
      });
    });
  });
  describe('telling the room', () => {
    it('reaches a reader when the owner saves', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota', '<p>Tuesday is yours</p>');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);

      const arrived = nextEvent<{ title: string; content: string }>(listening, 'note:updated');
      await saveNote(owner, note.id, { content: '<p>Wednesday is yours</p>' });

      expect((await arrived).content).to.equal('<p>Wednesday is yours</p>');
    });

    it('reaches the owner when somebody with an edit share saves', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const editor = await signIn('editor@example.com');

      await shareWith(owner, note.id, 'editor@example.com', 'edit');

      const listening = await socketFor(owner);
      await join(listening, note.id);

      const arrived = nextEvent<{ title: string }>(listening, 'note:updated');
      await saveNote(editor, note.id, { title: 'The new rota' });

      expect((await arrived).title).to.equal('The new rota');
    });

    it('leaves out the fields that mean something different to each reader', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);

      const arrived = nextEvent<Record<string, unknown>>(listening, 'note:updated');
      await saveNote(owner, note.id, { title: 'The new rota' });

      const change = await arrived;

      // owner and permission are worked out per reader, so a message two people
      // receive cannot carry either one
      expect(change).to.have.keys(['id', 'title', 'content', 'updatedAt']);

      // json has no date type, so the wire carries the string the client reads
      expect(change.updatedAt).to.be.a('string');
    });

    it('says when a note has been deleted', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);

      const arrived = nextEvent<{ id: number }>(listening, 'note:deleted');
      await request(server).delete(`/api/notes/${note.id}`).set('Cookie', owner);

      expect((await arrived).id).to.equal(note.id);
    });

    it('tells an account when a note is shared with it, without joining anything', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      const listening = await socketFor(reader);

      const arrived = nextEvent<{ noteId: number }>(listening, 'share:granted');
      await shareWith(owner, note.id, 'reader@example.com');

      expect((await arrived).noteId).to.equal(note.id);
    });

    it('ignores a socket id that names the room rather than a socket', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const watching = await socketFor(reader);
      await join(watching, note.id);

      // ids and room names share a namespace, so an unchecked header could name
      // the note's own room and silence everybody in it
      const arrived = nextEvent<{ title: string }>(watching, 'note:updated');
      await saveNote(owner, note.id, { title: 'The new rota' }, `note:${note.id}`);

      expect((await arrived).title).to.equal('The new rota');
    });

    it('ignores a socket id belonging to somebody else', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const watching = await socketFor(reader);
      await join(watching, note.id);

      const arrived = nextEvent<{ title: string }>(watching, 'note:updated');
      await saveNote(owner, note.id, { title: 'The new rota' }, watching.id);

      expect((await arrived).title).to.equal('The new rota');
    });

    it('does not send a save back to the socket that made it', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const saving = await socketFor(owner);
      const watching = await socketFor(reader);

      await join(saving, note.id);
      await join(watching, note.id);

      const echo = heardNothing(saving, 'note:updated');
      const arrived = nextEvent<{ title: string }>(watching, 'note:updated');

      await saveNote(owner, note.id, { title: 'The new rota' }, saving.id);

      expect((await arrived).title).to.equal('The new rota');
      expect(await echo, 'the saving socket heard its own change').to.equal(true);
    });
  });
  describe('taking a share back', () => {
    it('tells the account it has lost the note', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);

      const arrived = nextEvent<{ noteId: number }>(listening, 'share:revoked');
      await unshare(owner, note.id, await userId('reader@example.com'));

      expect((await arrived).noteId).to.equal(note.id);
    });

    it('stops the note reaching them afterwards', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);

      await unshare(owner, note.id, await userId('reader@example.com'));

      // still connected, and still in a room it joined while the share stood -
      // unless the revoke took the room away
      const heard = heardNothing(listening, 'note:updated');
      await saveNote(owner, note.id, { title: 'The new rota' });

      expect(await heard, 'an ex-reader was still receiving the note').to.equal(true);
    });

    it('refuses to let them join it again', async () => {
      const owner = await signIn('owner@example.com');
      const note = await createNote(owner, 'Rota');
      const reader = await signIn('reader@example.com');

      await shareWith(owner, note.id, 'reader@example.com');

      const listening = await socketFor(reader);
      await join(listening, note.id);
      await unshare(owner, note.id, await userId('reader@example.com'));

      expect(await join(listening, note.id)).to.deep.equal({
        ok: false,
        error: 'Note not found',
      });
    });
  });
});

import { expect } from 'chai';

import { sanitiseHtml } from '../src/utils/sanitiseHtml.js';

describe('sanitiseHtml', () => {
  describe('what it takes out', () => {
    it('drops a script and the code inside it', () => {
      expect(sanitiseHtml('<p>hi</p><script>alert(1)</script>')).to.equal('<p>hi</p>');
    });

    it('drops an event handler and keeps the paragraph', () => {
      expect(sanitiseHtml('<p onclick="alert(1)">hi</p>')).to.equal('<p>hi</p>');
    });

    it('drops an image, which the editor cannot write', () => {
      expect(sanitiseHtml('<img src=x onerror=alert(1)>')).to.equal('');
    });

    it('drops a javascript href but keeps the words', () => {
      const cleaned = sanitiseHtml('<a href="javascript:alert(1)">click</a>');

      expect(cleaned).to.not.contain('javascript:');
      expect(cleaned).to.not.contain('href');
      expect(cleaned).to.contain('click');
    });

    it('drops an iframe', () => {
      expect(sanitiseHtml('<iframe src="https://example.com"></iframe>')).to.equal('');
    });

    it('drops a style attribute holding anything but an alignment', () => {
      expect(sanitiseHtml('<p style="position:fixed">hi</p>')).to.equal('<p>hi</p>');
    });

    it('drops a property smuggled in beside a real alignment', () => {
      // the whole reason text-align is allowed by value rather than by name
      const smuggled = '<p style="text-align:center;position:fixed;top:0">hi</p>';

      expect(sanitiseHtml(smuggled)).to.equal('<p style="text-align:center">hi</p>');
    });

    it('drops a url payload sitting next to an alignment', () => {
      const payload = '<p style="text-align:left;background:url(javascript:alert(1))">hi</p>';

      expect(sanitiseHtml(payload)).to.not.contain('javascript');
    });

    it('drops an alignment that is not one of the four', () => {
      expect(sanitiseHtml('<p style="text-align:expression(alert(1))">hi</p>')).to.equal(
        '<p>hi</p>',
      );
    });

    it('drops an alignment on a block the editor cannot align', () => {
      // style is allowed on the alignable blocks and nowhere else, so a list
      // item carrying one did not come from the editor
      expect(sanitiseHtml('<li style="text-align:center">hi</li>')).to.contain('<li>hi</li>');
    });

    it('drops a class the editor would never write', () => {
      expect(sanitiseHtml('<p class="anything">hi</p>')).to.equal('<p>hi</p>');
    });
  });

  describe('what it keeps', () => {
    it('keeps every heading level, not only the one the toolbar offers', () => {
      const headings = '<h1>a</h1><h2>b</h2><h3>c</h3><h4>d</h4><h5>e</h5><h6>f</h6>';

      expect(sanitiseHtml(headings)).to.equal(headings);
    });

    it('keeps the marks the editor can apply', () => {
      const marks = '<p><strong>a</strong><em>b</em><s>c</s><u>d</u><code>e</code></p>';

      expect(sanitiseHtml(marks)).to.equal(marks);
    });

    it('keeps lists, quotes and rules', () => {
      const blocks = '<ul><li>a</li></ul><blockquote><p>b</p></blockquote><hr />';

      expect(sanitiseHtml(blocks)).to.equal(blocks);
    });

    it('keeps where an ordered list starts', () => {
      expect(sanitiseHtml('<ol start="3"><li>a</li></ol>')).to.equal(
        '<ol start="3"><li>a</li></ol>',
      );
    });

    it('keeps the language on a code block', () => {
      const code = '<pre><code class="language-ts">const a = 1;</code></pre>';

      expect(sanitiseHtml(code)).to.equal(code);
    });

    it('keeps a real link, with the attributes the editor gives it', () => {
      const link = '<a href="https://example.com" target="_blank" rel="noopener">go</a>';
      const cleaned = sanitiseHtml(link);

      expect(cleaned).to.contain('href="https://example.com"');
      expect(cleaned).to.contain('target="_blank"');
    });

    it('puts rel back on a link that arrived without one', () => {
      expect(sanitiseHtml('<a href="https://example.com">go</a>')).to.contain(
        'rel="noopener noreferrer nofollow"',
      );
    });

    it('keeps an alignment on a paragraph and on a heading', () => {
      const aligned = '<p style="text-align:center">a</p><h2 style="text-align:right">b</h2>';

      expect(sanitiseHtml(aligned)).to.equal(aligned);
    });

    it('keeps each of the four alignments', () => {
      for (const align of ['left', 'right', 'center', 'justify']) {
        expect(sanitiseHtml(`<p style="text-align:${align}">a</p>`)).to.equal(
          `<p style="text-align:${align}">a</p>`,
        );
      }
    });

    it('leaves an empty body empty', () => {
      expect(sanitiseHtml('')).to.equal('');
    });
  });
});

import { expect } from 'chai';
import express, { type Express } from 'express';
import request from 'supertest';

import { createApp } from '../src/app.js';
import { isDatabaseReachable, prisma } from '../src/db/prisma.js';
import { errorHandler } from '../src/middleware/errorHandler.js';
import { createLimiter } from '../src/middleware/rateLimit.js';
import { isCommonPassword } from '../src/utils/commonPasswords.js';
import { maxPasswordBytes } from '../src/utils/password.js';
import { readToken, signToken } from '../src/utils/token.js';

const app = createApp();

const password = 'correct horse battery';

async function signIn(email: string): Promise<ReturnType<typeof request.agent>> {
  const agent = request.agent(app);
  await agent.post('/api/auth/register').send({ email, password });

  return agent;
}

async function clearTables(): Promise<void> {
  await prisma.noteShare.deleteMany();
  await prisma.note.deleteMany();
  await prisma.user.deleteMany();
}

after(async () => {
  await prisma.$disconnect();
});

describe('rate limiting', () => {
  /** An app with one limited route, so a real limit can be reached in a test. */
  function limited(max: number): Express {
    const small = express();

    small.use('/thing', createLimiter(max, 'Too many attempts.', 'test'), (_req, res) => {
      res.json({ ok: true });
    });
    small.use(errorHandler);

    return small;
  }

  it('lets requests through up to the limit', async () => {
    const small = limited(2);

    expect((await request(small).get('/thing')).status).to.equal(200);
    expect((await request(small).get('/thing')).status).to.equal(200);
  });

  it('answers 429 past the limit, in the usual error envelope', async () => {
    const small = limited(2);

    await request(small).get('/thing');
    await request(small).get('/thing');

    const response = await request(small).get('/thing');

    expect(response.status).to.equal(429);
    expect(response.body.error.message).to.equal('Too many attempts.');
  });

  it('counts each limiter separately', async () => {
    const one = limited(1);
    const two = limited(1);

    await request(one).get('/thing');

    expect((await request(two).get('/thing')).status).to.equal(200);
  });
});

describe('password rules', () => {
  it('knows the guesses an attacker starts with', () => {
    expect(isCommonPassword('password123')).to.equal(true);
    expect(isCommonPassword('PASSWORD123')).to.equal(true);
    expect(isCommonPassword('correct horse battery')).to.equal(false);
  });

  describe('registering', function () {
    before(async function () {
      if (!(await isDatabaseReachable())) {
        this.skip();
      }
    });

    beforeEach(clearTables);

    it('refuses a password bcrypt would truncate', async () => {
      const response = await request(app)
        .post('/api/auth/register')
        .send({ email: 'long@example.com', password: 'a'.repeat(maxPasswordBytes + 1) });

      expect(response.status).to.equal(400);
      expect(response.body.error.details[0].field).to.equal('password');
    });

    it('accepts one exactly at the limit', async () => {
      const response = await request(app)
        .post('/api/auth/register')
        .send({ email: 'edge@example.com', password: 'a'.repeat(maxPasswordBytes) });

      expect(response.status).to.equal(201);
    });

    it('still logs in an account whose password is past the cap', async () => {
      // registering at the limit and logging in past it is the same case as an
      // account made before the cap existed: bcrypt only ever read 72 bytes
      const at = 'a'.repeat(maxPasswordBytes);

      await request(app)
        .post('/api/auth/register')
        .send({ email: 'legacy@example.com', password: at });

      const login = await request(app)
        .post('/api/auth/login')
        .send({ email: 'legacy@example.com', password: `${at}and then some more` });

      expect(login.status).to.equal(200);
    });

    it('counts bytes rather than characters', async () => {
      // a four byte character, so 20 of them are past the cap at 20 characters
      const response = await request(app)
        .post('/api/auth/register')
        .send({ email: 'wide@example.com', password: '\u{1F600}'.repeat(20) });

      expect(response.status).to.equal(400);
    });

    it('refuses a common password', async () => {
      const response = await request(app)
        .post('/api/auth/register')
        .send({ email: 'common@example.com', password: 'password123' });

      expect(response.status).to.equal(400);
      expect(response.body.error.details[0].message).to.contain('too common');
    });

    it('still refuses a short one', async () => {
      const response = await request(app)
        .post('/api/auth/register')
        .send({ email: 'short@example.com', password: 'abc' });

      expect(response.status).to.equal(400);
    });
  });
});

describe('changing a password', function () {
  before(async function () {
    if (!(await isDatabaseReachable())) {
      this.skip();
    }
  });

  beforeEach(clearTables);

  it('needs a session', async () => {
    const response = await request(app)
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'a whole new secret' });

    expect(response.status).to.equal(401);
  });

  it('refuses the wrong current password', async () => {
    const agent = await signIn('wrong@example.com');

    const response = await agent
      .patch('/api/auth/password')
      .send({ currentPassword: 'not the one', newPassword: 'a whole new secret' });

    expect(response.status).to.equal(401);
  });

  it('refuses a new password the same as the old', async () => {
    const agent = await signIn('same@example.com');

    const response = await agent
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: password });

    expect(response.status).to.equal(400);
  });

  it('applies the rules to the new password too', async () => {
    const agent = await signIn('rules@example.com');

    const response = await agent
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'password123' });

    expect(response.status).to.equal(400);
  });

  it('changes it, and the new password logs in', async () => {
    const agent = await signIn('change@example.com');

    const changed = await agent
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'a whole new secret' });

    expect(changed.status).to.equal(204);

    const login = await request(app)
      .post('/api/auth/login')
      .send({ email: 'change@example.com', password: 'a whole new secret' });

    expect(login.status).to.equal(200);
  });

  it('leaves the session that changed it signed in', async () => {
    const agent = await signIn('stays@example.com');

    const changed = await agent
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'a whole new secret' });

    expect(changed.status).to.equal(204);
    expect((await agent.get('/api/auth/me')).status).to.equal(200);
  });

  it('signs the other sessions out', async () => {
    const first = await signIn('other@example.com');

    // a second sign-in of the same account, holding the token as it was
    const second = request.agent(app);
    await second.post('/api/auth/login').send({ email: 'other@example.com', password });

    expect((await second.get('/api/auth/me')).status).to.equal(200);

    await first
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'a whole new secret' });

    expect((await second.get('/api/auth/me')).status).to.equal(401);
  });

  it('stops the old token reaching the notes routes too', async () => {
    const first = await signIn('notes@example.com');

    const second = request.agent(app);
    await second.post('/api/auth/login').send({ email: 'notes@example.com', password });

    await first
      .patch('/api/auth/password')
      .send({ currentPassword: password, newPassword: 'a whole new secret' });

    expect((await second.get('/api/notes')).status).to.equal(401);
  });
});

describe('session tokens', () => {
  it('carries the version it was signed with', () => {
    const session = readToken(signToken(7, 3));

    expect(session?.userId).to.equal(7);
    expect(session?.tokenVersion).to.equal(3);
  });

  it('refuses a token that has been cut about', () => {
    expect(readToken(signToken(7, 3).split('.').slice(0, 2).join('.'))).to.equal(null);
  });

  it('refuses rubbish', () => {
    expect(readToken('not-a-token')).to.equal(null);
  });
});

